"use client"

import { useEffect, useRef } from "react"
import { useAtomValue, useStore } from "jotai"

import styles from "../ipod-classic.module.css"
import { brickStatusAtom, engineAtom, isInertAtom } from "../lib/atoms"
import {
  brickStatus,
  createBrickGame,
  createLcdInk,
  createLcdRenderer,
  drawField,
  FIELD_HEIGHT,
  FIELD_WIDTH,
  INITIAL_BRICK_STATUS,
  tickMs,
} from "../lib/brick-engine"
import { BRICK_PADDLE_STEER } from "../lib/constants"

/** Catching up after a stall is capped, so the ball never teleports. */
const MAX_CATCH_UP_TICKS = 10

export function BrickGame() {
  const store = useStore()
  const engine = useAtomValue(engineAtom)
  const { message } = useAtomValue(brickStatusAtom)
  const canvasRef = useRef<HTMLCanvasElement>(null)

  useEffect(() => {
    const canvas = canvasRef.current
    if (!canvas || !engine) return
    const game = createBrickGame()
    const lcd = createLcdInk(FIELD_WIDTH, FIELD_HEIGHT)
    const { state } = game
    const isPaused = () => store.get(isInertAtom)
    let frame: number | undefined
    let lastTime: number | undefined
    let backlog = 0
    let needsDraw = false
    let steer = 0
    let hasSteered = false

    function draw() {
      drawField(state, lcd.drive)
      needsDraw = false
    }

    // Fixed ticks keep the physics identical at any frame rate.
    function step(now: number) {
      const elapsed = lastTime === undefined ? 0 : now - lastTime
      const interval = tickMs(state.level)
      const paused = isPaused()
      lastTime = now
      backlog = Math.min(backlog + elapsed, interval * MAX_CATCH_UP_TICKS)

      let ticked = false
      while (backlog >= interval) {
        backlog -= interval
        ticked = true
        if (paused) continue
        game.movePaddle(steer * BRICK_PADDLE_STEER)
        hasSteered ||= steer !== 0
        game.tick()
      }
      if (ticked) {
        draw()
        store.set(brickStatusAtom, brickStatus(state))
      }
      const isFading = lcd.fade(elapsed)
      if (ticked || isFading) renderer.paint()

      const isMoving =
        !paused && (state.isBallInPlay || state.serveTicks > 0 || steer !== 0)
      frame =
        isMoving || needsDraw || isFading
          ? requestAnimationFrame(step)
          : undefined
    }

    function start() {
      if (frame !== undefined) return
      lastTime = undefined
      frame = requestAnimationFrame(step)
    }

    function movePaddle(fraction: number) {
      game.movePaddle(fraction)
      needsDraw = true
      start()
    }

    draw()
    lcd.settle()
    const renderer = createLcdRenderer(canvas, lcd)
    store.set(brickStatusAtom, INITIAL_BRICK_STATUS)
    const unsubscribe = store.sub(isInertAtom, () => {
      if (!isPaused()) start()
    })

    engine.menu.registerBrick({
      movePaddle,
      steerPaddle(direction) {
        // A tap too short to reach a tick still nudges the paddle once.
        if (direction === 0 && !hasSteered && !isPaused()) {
          movePaddle(steer * BRICK_PADDLE_STEER)
        }
        steer = direction
        hasSteered = false
        start()
      },
      launchBall() {
        game.launchBall()
        needsDraw = true
        store.set(brickStatusAtom, brickStatus(state))
        start()
      },
    })

    return () => {
      engine.menu.registerBrick(null)
      unsubscribe()
      if (frame !== undefined) cancelAnimationFrame(frame)
      renderer.destroy()
    }
  }, [store, engine])

  return (
    <div className={styles.brickScreen}>
      <canvas
        ref={canvasRef}
        className={styles.brickCanvas}
        width={FIELD_WIDTH}
        height={FIELD_HEIGHT}
        aria-hidden
      />
      <p className={styles.visuallyHidden} role="status">
        {message}
      </p>
    </div>
  )
}

"use client"

import {
  useEffect,
  useRef,
  useState,
  type CSSProperties,
  type KeyboardEvent,
  type PointerEvent,
} from "react"
import { useAtomValue, useStore } from "jotai"

import styles from "../ipod-classic.module.css"
import {
  engineAtom,
  playbackAtom,
  scrollTargetAtom,
  seekAtom,
  selectHoldMsAtom,
} from "../lib/atoms"
import {
  HOLD_MS,
  HOLD_REPEAT_MS,
  KEY_REPEAT_DELAY_MS,
  KEY_REPEAT_INTERVAL_MS,
  SCROLL_WHEEL_PERCENT,
  SELECT_BUTTON_PERCENT,
} from "../lib/constants"
import type { IpodEngine } from "../lib/engine"
import { createHoldTimer } from "../lib/timers"
import type { ScrollTarget } from "../lib/types"
import { bindPressAndHold, bindWheelGesture } from "../lib/wheel-gesture"
import { MenuLabel, PlayPauseIcon, SkipIcon } from "./icons"

type Button = "menu" | "select" | "playPause" | "back" | "forward"
type HoldButton = Exclude<Button, "menu" | "playPause">

type KeyAction =
  | { kind: "scroll" | "steer"; step: 1 | -1 }
  | {
      kind: "hold"
      button: HoldButton
      duration?: number
      repeatInterval?: number
    }
  | { kind: "press"; button: Button }
  | { kind: "none" }

const LONG_PRESS: Record<
  HoldButton,
  (wheel: IpodEngine["wheel"], repeat: boolean) => void
> = {
  select: (wheel) => wheel.selectHold(),
  back: (wheel, repeat) => wheel.backHold(repeat),
  forward: (wheel, repeat) => wheel.forwardHold(repeat),
}

const isSkip = (button: Button) => button === "back" || button === "forward"

function keyAction(
  key: string,
  target: ScrollTarget,
  selectHoldMs: number | null
): KeyAction | undefined {
  switch (key) {
    case "ArrowUp":
    case "ArrowDown":
      if (target === "brick") return { kind: "none" }
      // Lists scroll down with ArrowDown; sliders go up with ArrowUp.
      return {
        kind: "scroll",
        step: key === (target === "list" ? "ArrowDown" : "ArrowUp") ? 1 : -1,
      }
    case "ArrowLeft":
    case "ArrowRight": {
      const isLeft = key === "ArrowLeft"
      if (target === "seek") return { kind: "scroll", step: isLeft ? -1 : 1 }
      if (target === "brick") return { kind: "steer", step: isLeft ? -1 : 1 }
      if (target === "volume") {
        return {
          kind: "hold",
          button: isLeft ? "back" : "forward",
          repeatInterval: HOLD_REPEAT_MS,
        }
      }
      return { kind: "press", button: isLeft ? "menu" : "select" }
    }
    case "Enter":
      return selectHoldMs === null
        ? { kind: "press", button: "select" }
        : { kind: "hold", button: "select", duration: selectHoldMs }
    case " ":
      return { kind: "press", button: "playPause" }
    case "Escape":
      return { kind: "press", button: "menu" }
  }
}

export function ClickWheel() {
  const store = useStore()
  const isPlaying = useAtomValue(playbackAtom).isPlaying
  const disableSkip = useAtomValue(seekAtom).isSeeking
  const ringRef = useRef<HTMLDivElement>(null)
  const backRef = useRef<HTMLButtonElement>(null)
  const forwardRef = useRef<HTMLButtonElement>(null)
  const selectRef = useRef<HTMLButtonElement>(null)
  const isDraggingRef = useRef(false)
  const [isDragging, setIsDragging] = useState(false)
  const keyRef = useRef<{
    key?: string
    action?: KeyAction
    pressedAt: number
    target?: ScrollTarget
    selectHoldMs?: number | null
    timer?: ReturnType<typeof createHoldTimer>
  }>({ pressedAt: 0 })

  // Listeners read the store directly, so they always see the current screen.
  const wheel = () => store.get(engineAtom)?.wheel
  const isSkipDisabled = () => store.get(seekAtom).isSeeking

  function press(button: Button) {
    if (isSkip(button) && isSkipDisabled()) return
    wheel()?.[button]()
  }

  function hold(button: HoldButton, repeat: boolean) {
    const handlers = wheel()
    if (!handlers || (isSkip(button) && isSkipDisabled())) return
    LONG_PRESS[button](handlers, repeat)
  }

  function focusRing() {
    if (matchMedia("(any-pointer: fine)").matches) {
      ringRef.current?.focus({ preventScroll: true })
    }
  }

  function cancelKey(commit: boolean) {
    const state = keyRef.current
    const { action } = state
    const didFire = state.timer?.stop() ?? false
    state.key = undefined
    state.action = undefined
    if (action?.kind === "scroll") {
      if (!isDraggingRef.current) wheel()?.dragEnd()
    } else if (action?.kind === "steer") {
      wheel()?.steer(null)
    } else if (
      (action?.kind === "press" || action?.kind === "hold") &&
      commit &&
      !didFire
    ) {
      press(action.button)
    }
  }

  function fireKey(repeat: boolean) {
    const state = keyRef.current
    // The screen changed under the held key, so it no longer means the same.
    if (
      store.get(scrollTargetAtom) !== state.target ||
      store.get(selectHoldMsAtom) !== state.selectHoldMs
    ) {
      cancelKey(false)
      return
    }
    const { action } = state
    if (action?.kind === "scroll") {
      wheel()?.keyScroll(action.step, performance.now() - state.pressedAt)
    } else if (action?.kind === "hold") {
      hold(action.button, repeat)
    }
  }

  function handleKeyDown(event: KeyboardEvent<HTMLDivElement>) {
    if (event.ctrlKey || event.metaKey || event.altKey) {
      cancelKey(false)
      return
    }
    const target = store.get(scrollTargetAtom)
    const selectHoldMs = store.get(selectHoldMsAtom)
    const action = keyAction(event.key, target, selectHoldMs)
    if (!action) return
    event.preventDefault()
    event.stopPropagation()
    const state = keyRef.current
    if (event.repeat || event.key === state.key) return

    cancelKey(false)
    Object.assign(state, {
      key: event.key,
      action,
      pressedAt: performance.now(),
      target,
      selectHoldMs,
    })
    state.timer ??= createHoldTimer(fireKey)

    if (action.kind === "scroll") {
      if (!isDraggingRef.current) wheel()?.dragStart()
      wheel()?.keyScroll(action.step, 0)
      state.timer.start(KEY_REPEAT_DELAY_MS, KEY_REPEAT_INTERVAL_MS)
    } else if (action.kind === "steer") {
      wheel()?.steer(action.step)
    } else if (action.kind === "hold") {
      state.timer.start(action.duration ?? HOLD_MS, action.repeatInterval)
    }
  }

  function handleKeyUp(event: KeyboardEvent<HTMLDivElement>) {
    if (event.key !== keyRef.current.key) return
    event.preventDefault()
    event.stopPropagation()
    cancelKey(true)
  }

  function handlePointerUp(event: PointerEvent<HTMLDivElement>) {
    const isRealMouse =
      event.pointerType === "mouse" && (event.width > 0 || event.height > 0)
    if (isRealMouse) focusRing()
  }

  useEffect(() => {
    const ring = ringRef.current
    if (!ring) return
    // A key-driven scroll already opened the drag, so it is not repeated.
    const setDragging = (dragging: boolean) => {
      isDraggingRef.current = dragging
      setIsDragging(dragging)
      if (keyRef.current.action?.kind === "scroll") return
      if (dragging) wheel()?.dragStart()
      else wheel()?.dragEnd()
    }
    return bindWheelGesture(ring, {
      excludeRadiusRatio: SELECT_BUTTON_PERCENT / SCROLL_WHEEL_PERCENT,
      onScroll: (scroll) => wheel()?.scroll(scroll),
      onDragStart: () => setDragging(true),
      onDragEnd: () => setDragging(false),
    })
    // `wheel` reads the store at call time.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [store])

  useEffect(() => {
    const buttons: [HTMLElement | null, HoldButton][] = [
      [backRef.current, "back"],
      [forwardRef.current, "forward"],
      [selectRef.current, "select"],
    ]
    const unbinds = buttons.map(([element, button]) => {
      if (!element) return
      return bindPressAndHold(element, () => {
        const selectHoldMs = store.get(selectHoldMsAtom)
        const isSelect = button === "select"
        return {
          duration: isSelect ? (selectHoldMs ?? HOLD_MS) : HOLD_MS,
          repeatInterval: isSkip(button) ? HOLD_REPEAT_MS : undefined,
          // Enter on Select is the wheel's own key, handled above.
          keyboard: !isSelect,
          disabled: isSelect && selectHoldMs === null,
          onLongPress: (repeat) => hold(button, repeat),
        }
      })
    })
    const keyState = keyRef.current
    return () => {
      unbinds.forEach((unbind) => unbind?.())
      keyState.timer?.stop()
    }
    // `hold` reads the store at call time.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [store])

  return (
    <div
      className={styles.clickWheel}
      data-dragging={isDragging || undefined}
      dir="ltr"
      tabIndex={-1}
      style={
        {
          "--select-button-pct": `${SELECT_BUTTON_PERCENT}%`,
          "--scroll-wheel-pct": `${SCROLL_WHEEL_PERCENT}%`,
        } as CSSProperties
      }
      onKeyDown={handleKeyDown}
      onKeyUp={handleKeyUp}
      onBlur={() => cancelKey(false)}
      onPointerUp={handlePointerUp}
    >
      <button
        type="button"
        className={`${styles.wheelButton} ${styles.menuButton}`}
        aria-label="Menu"
        onClick={() => press("menu")}
      >
        <MenuLabel />
      </button>
      <button
        ref={backRef}
        type="button"
        className={`${styles.wheelButton} ${styles.backButton}`}
        aria-label="Back"
        aria-disabled={disableSkip}
        onClick={() => press("back")}
      >
        <SkipIcon />
      </button>
      <button
        ref={forwardRef}
        type="button"
        className={`${styles.wheelButton} ${styles.forwardButton}`}
        aria-label="Forward"
        aria-disabled={disableSkip}
        onClick={() => press("forward")}
      >
        <SkipIcon />
      </button>
      <button
        type="button"
        className={`${styles.wheelButton} ${styles.playPauseButton}`}
        aria-label={isPlaying ? "Pause" : "Play"}
        onClick={() => press("playPause")}
      >
        <PlayPauseIcon />
      </button>
      <div className={styles.wheelDividers} />
      <div
        ref={ringRef}
        className={styles.scrollWheel}
        aria-hidden
        tabIndex={-1}
        onPointerDown={focusRing}
      />
      <button
        ref={selectRef}
        type="button"
        className={styles.selectButton}
        aria-label="Select"
        onClick={() => press("select")}
      />
    </div>
  )
}

"use client"

import { useEffect, useRef, useState, type CSSProperties } from "react"

import styles from "../ipod-classic.module.css"

/** Scrolls text that does not fit, after a pause, like the iPod's title. */
export function Marquee({
  text,
  resetKey,
}: {
  text: string
  /** Restarts the scroll, e.g. for a new song with the same title. */
  resetKey?: string
}) {
  const containerRef = useRef<HTMLDivElement>(null)
  const copyRef = useRef<HTMLSpanElement>(null)
  const [widths, setWidths] = useState({ container: 0, copy: 0 })

  useEffect(() => {
    const container = containerRef.current
    const copy = copyRef.current
    if (!container || !copy) return
    const observer = new ResizeObserver(() =>
      setWidths({ container: container.clientWidth, copy: copy.offsetWidth })
    )
    observer.observe(container)
    observer.observe(copy)
    return () => observer.disconnect()
  }, [text, resetKey])

  const isScrolling = widths.copy - widths.container > 1

  return (
    <div
      ref={containerRef}
      className={styles.marquee}
      data-scrolling={isScrolling || undefined}
      dir="auto"
    >
      <div
        key={`${resetKey ?? ""}\0${text}`}
        className={styles.marqueeTrack}
        style={{ "--marquee-copy-width": widths.copy } as CSSProperties}
      >
        <span ref={copyRef} className={styles.marqueeCopy}>
          {text}
        </span>
        {isScrolling && (
          <span className={styles.marqueeCopy} aria-hidden>
            {text}
          </span>
        )}
      </div>
    </div>
  )
}

"use client"

import { useLayoutEffect, useRef } from "react"
import { useAtomValue } from "jotai"

import styles from "../ipod-classic.module.css"
import { settingsAtom } from "../lib/atoms"
import { settingValue, type MenuItem } from "../lib/menu"

/** Scrolls only the list, never the page, to show the row. */
function revealRow(list: HTMLElement, row: HTMLElement) {
  const top = row.offsetTop
  const bottom = top + row.offsetHeight
  if (top < list.scrollTop) list.scrollTop = top
  else if (bottom > list.scrollTop + list.clientHeight) {
    list.scrollTop = bottom - list.clientHeight
  }
}

export function MenuList({
  items,
  selectedIndex,
  idPrefix,
  labelledBy,
  shouldFocus,
  restoredScrollTop,
  listRef,
}: {
  items: MenuItem[]
  selectedIndex: number
  idPrefix: string
  labelledBy: string
  shouldFocus: boolean
  restoredScrollTop: number | undefined
  /** Returns a cleanup, so an outgoing list cannot unregister the new one. */
  listRef: (element: HTMLUListElement) => () => void
}) {
  const ref = useRef<HTMLUListElement>(null)
  const settings = useAtomValue(settingsAtom)

  // Mount only: restore where the list was left, or reveal the selection.
  useLayoutEffect(() => {
    const list = ref.current
    if (!list) return
    if (restoredScrollTop !== undefined) list.scrollTop = restoredScrollTop
    if (shouldFocus) list.focus({ preventScroll: true })
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [])

  useLayoutEffect(() => {
    const list = ref.current
    const row = list?.children[selectedIndex]
    if (list && row instanceof HTMLElement) revealRow(list, row)
  }, [selectedIndex, items.length])

  return (
    <ul
      ref={(element) => {
        if (!element) return
        ref.current = element
        return listRef(element)
      }}
      className={styles.menuItems}
      role="listbox"
      tabIndex={0}
      aria-activedescendant={`${idPrefix}-${selectedIndex}`}
      aria-labelledby={labelledBy}
    >
      {items.map((item, index) => {
        const isInfo = item.action === "info"
        const isSelected = index === selectedIndex
        const value = settingValue(item, settings)
        return (
          <li
            key={item.id}
            id={`${idPrefix}-${index}`}
            className={styles.menuItem}
            data-action={item.action}
            data-selected={isSelected || undefined}
            data-centered={(isInfo && item.centered) || undefined}
            role={isInfo ? undefined : "option"}
            aria-selected={isInfo ? undefined : isSelected}
          >
            <span className={styles.itemTitle} dir="auto">
              {item.title}
            </span>
            {value !== undefined && (
              <span className={styles.itemValue} dir="auto">
                {value}
              </span>
            )}
            {item.action === "navigate" && (
              <span className={styles.chevron} aria-hidden />
            )}
          </li>
        )
      })}
    </ul>
  )
}

"use client"

import { useEffect, useRef, useState } from "react"
import { useAtomValue } from "jotai"

import styles from "../ipod-classic.module.css"
import {
  engineAtom,
  isAdjustingVolumeAtom,
  playbackAtom,
  seekAtom,
  settingsAtom,
} from "../lib/atoms"
import {
  RepeatAllIcon,
  RepeatOneIcon,
  ShuffleIcon,
  VolumeHighIcon,
  VolumeLowIcon,
} from "./icons"
import { Marquee } from "./marquee"
import { ProgressBar } from "./progress-bar"

const integer = new Intl.NumberFormat("en-US")
const units = {
  hour: new Intl.NumberFormat("en-US", {
    style: "unit",
    unit: "hour",
    unitDisplay: "long",
  }),
  minute: new Intl.NumberFormat("en-US", {
    style: "unit",
    unit: "minute",
    unitDisplay: "long",
  }),
  second: new Intl.NumberFormat("en-US", {
    style: "unit",
    unit: "second",
    unitDisplay: "long",
  }),
}
const list = new Intl.ListFormat("en-US")

function formatTime(seconds: number) {
  const value = Math.max(0, Math.floor(seconds))
  return `${Math.floor(value / 60)}:${String(value % 60).padStart(2, "0")}`
}

/** "1 minute and 5 seconds", for the scrubber's spoken value. */
function spokenDuration(seconds: number) {
  const value = Math.max(0, Math.floor(seconds))
  const parts = (
    [
      ["hour", Math.floor(value / 3600)],
      ["minute", Math.floor(value / 60) % 60],
      ["second", value % 60],
    ] as const
  )
    .filter(([, amount]) => amount > 0)
    .map(([unit, amount]) => units[unit].format(amount))
  return parts.length ? list.format(parts) : units.second.format(0)
}

const PLAY_MODE_LABELS: Record<string, string> = {
  "shuffle-off": "Shuffle on",
  "shuffle-one": "Shuffle on, Repeat one",
  "shuffle-all": "Shuffle on, Repeat all",
  "ordered-one": "Repeat one",
  "ordered-all": "Repeat all",
}

export function NowPlaying({
  labelledBy,
  shouldFocus,
}: {
  labelledBy: string
  shouldFocus: boolean
}) {
  const playback = useAtomValue(playbackAtom)
  const seek = useAtomValue(seekAtom)
  const isAdjustingVolume = useAtomValue(isAdjustingVolumeAtom)
  const { shuffle, repeat } = useAtomValue(settingsAtom)
  const sliders = useAtomValue(engineAtom)?.sliders
  const ref = useRef<HTMLDivElement>(null)

  const song = playback.queue[playback.currentTrackIndex]
  const { duration } = playback
  const time =
    seek.isSeeking && seek.previewTime !== undefined
      ? seek.previewTime
      : playback.currentTime
  const hasDuration = Number.isFinite(duration) && duration > 0
  const elapsed = hasDuration ? formatTime(time) : ""
  const remaining = hasDuration
    ? `-${formatTime(Math.ceil(duration - time))}`
    : ""
  const scrubValue = hasDuration ? Math.floor(time) : 0
  const volume = Math.round(playback.volume * 100)
  const isShuffled = shuffle === "songs"
  const playModesLabel =
    PLAY_MODE_LABELS[`${isShuffled ? "shuffle" : "ordered"}-${repeat}`]

  const mode = isAdjustingVolume
    ? "volume"
    : seek.isSeeking
      ? "scrubbing"
      : "progress"
  // The pane sliding out keeps its content until it is off screen.
  const [pane, setPane] = useState<"volume" | "scrubbing">("volume")
  const shownPane = mode === "progress" ? pane : mode
  if (shownPane !== pane) setPane(shownPane)

  useEffect(() => {
    if (shouldFocus) ref.current?.focus({ preventScroll: true })
    // Focus only when this page arrives.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [])

  const labels = (
    <>
      <span>{elapsed}</span>
      <span>{remaining}</span>
    </>
  )

  return (
    <div
      ref={ref}
      className={styles.nowPlaying}
      role="group"
      aria-labelledby={labelledBy}
      tabIndex={0}
    >
      <div className={styles.nowPlayingIndex}>
        <span>
          {integer.format(playback.queuePosition + 1)} of{" "}
          {integer.format(playback.queue.length)}
        </span>
        {playModesLabel && (
          <>
            <div className={styles.playModifier} aria-hidden>
              {repeat === "one" && <RepeatOneIcon />}
              {repeat === "all" && <RepeatAllIcon />}
              {isShuffled && <ShuffleIcon />}
            </div>
            <span className={styles.visuallyHidden}>{playModesLabel}</span>
          </>
        )}
      </div>

      {song && (
        <div className={styles.nowPlayingInfo}>
          <div className={styles.songTitle}>
            {song.url ? (
              <a
                className={styles.songTitleLink}
                href={song.url}
                target="_blank"
                rel="noopener noreferrer"
              >
                <Marquee text={song.name} resetKey={song.id} />
              </a>
            ) : (
              <Marquee text={song.name} resetKey={song.id} />
            )}
          </div>
          <div className={styles.artist} dir="auto">
            {song.artistName}
          </div>
          {song.albumName && (
            <div className={styles.album} dir="auto">
              {song.albumName}
            </div>
          )}
        </div>
      )}

      <div className={styles.progressPanes} data-mode={mode}>
        <div className={styles.timeAndProgress} aria-hidden>
          <ProgressBar value={time} max={duration} />
          <div className={styles.progressLabels}>{labels}</div>
        </div>

        <div
          className={styles.scrubber}
          data-inactive={shownPane !== "scrubbing" || undefined}
        >
          <ProgressBar
            variant="marker"
            value={scrubValue}
            max={duration}
            disabled={!playback.hasLoadedItem}
            label="Playback Progress"
            valueText={spokenDuration(scrubValue)}
            onFocus={sliders?.focusScrub}
            onInput={sliders?.scrub}
            onCommit={sliders?.commitScrub}
            onBlur={sliders?.blurScrub}
          />
          <div className={styles.progressLabels} aria-hidden>
            {labels}
          </div>
        </div>

        <div
          className={styles.volume}
          data-inactive={shownPane !== "volume" || undefined}
        >
          <VolumeLowIcon />
          <ProgressBar
            value={volume}
            max={100}
            label="Volume"
            valueText={`${volume}%`}
            onFocus={sliders?.focusVolume}
            onInput={sliders?.setVolume}
            onBlur={sliders?.blurVolume}
          />
          <VolumeHighIcon />
        </div>
      </div>
    </div>
  )
}

import styles from "../ipod-classic.module.css"

/**
 * The LCD's rounded bar, filled or with a diamond marker. With a `label` it
 * carries an invisible range input for keyboard and screen readers.
 */
export function ProgressBar({
  value,
  max,
  variant = "fill",
  label,
  valueText,
  disabled,
  onFocus,
  onInput,
  onCommit,
  onBlur,
}: {
  value: number
  max: number
  variant?: "fill" | "marker"
  label?: string
  valueText?: string
  disabled?: boolean
  onFocus?: () => void
  onInput?: (value: number) => void
  onCommit?: () => void
  onBlur?: () => void
}) {
  const percent = max > 0 ? Math.min(100, (value * 100) / max) : 0
  return (
    <div className={styles.progressBar}>
      {variant === "marker" ? (
        <div
          className={styles.progressMarker}
          style={{ left: `${percent}%` }}
        />
      ) : (
        <div className={styles.progressFill} style={{ width: `${percent}%` }} />
      )}
      {label && (
        <input
          className={styles.rangeInput}
          type="range"
          min={0}
          max={max}
          value={value}
          disabled={disabled}
          aria-label={label}
          aria-valuetext={valueText}
          onFocus={onFocus}
          onChange={(event) => onInput?.(event.currentTarget.valueAsNumber)}
          onPointerUp={onCommit}
          onKeyUp={onCommit}
          onBlur={onBlur}
        />
      )}
    </div>
  )
}

"use client"

import { useId, type CSSProperties, type RefObject } from "react"
import { useAtomValue } from "jotai"
import { AnimatePresence, motion, useReducedMotion } from "motion/react"

import styles from "../ipod-classic.module.css"
import { SAD_IPOD } from "../lib/assets"
import {
  isInertAtom,
  itemsAtom,
  navigationAtom,
  statusAtom,
  viewAtom,
} from "../lib/atoms"
import { BrickGame } from "./brick-game"
import { AppleLogo } from "./icons"
import { MenuList } from "./menu-list"
import { NowPlaying } from "./now-playing"
import { TitleBar } from "./title-bar"
import { useScreenKeyboard } from "./use-screen-keyboard"

const OFFLINE_MESSAGE = "You are not connected to the internet"

const slide = {
  enter: (back: boolean) => ({ x: back ? "-100%" : "100%" }),
  center: { x: 0 },
  exit: (back: boolean) => ({ x: back ? "100%" : "-100%" }),
}
const EASE_IN_OUT_SINE = [0.37, 0, 0.63, 1] as const

export function Screen({
  menuRef,
  registerList,
}: {
  menuRef: RefObject<HTMLDivElement | null>
  registerList: (element: HTMLUListElement) => () => void
}) {
  const status = useAtomValue(statusAtom)
  const isInert = useAtomValue(isInertAtom)
  const titleId = useId()

  return (
    <div className={styles.screen}>
      <p className={styles.visuallyHidden} role="status">
        {status.isOnline
          ? status.isBooting
            ? "Loading"
            : "Ready"
          : OFFLINE_MESSAGE}
      </p>

      {!status.isOnline ? (
        <OfflineOverlay />
      ) : (
        status.isBooting && (
          <div className={styles.overlay} aria-hidden>
            <AppleLogo className={styles.bootLogo} />
          </div>
        )
      )}

      <div className={styles.menuLayer} data-hidden={isInert || undefined}>
        <div ref={menuRef} className={styles.menu}>
          <TitleBar id={titleId} />
          <ScreenPages titleId={titleId} registerList={registerList} />
        </div>
      </div>
    </div>
  )
}

function OfflineOverlay() {
  return (
    <div className={styles.overlay} aria-hidden>
      <div className={styles.sadIpod}>
        <div
          className={styles.sadIpodIcon}
          style={{ "--mask": `url(${SAD_IPOD})` } as CSSProperties}
        />
        <p className={styles.errorMessage}>{OFFLINE_MESSAGE}</p>
      </div>
    </div>
  )
}

/** Each push or pop slides a new page in; the old one keeps its content. */
function ScreenPages({
  titleId,
  registerList,
}: {
  titleId: string
  registerList: (element: HTMLUListElement) => () => void
}) {
  const navigation = useAtomValue(navigationAtom)
  const view = useAtomValue(viewAtom)
  const items = useAtomValue(itemsAtom)
  const reduceMotion = useReducedMotion()
  const keyboard = useScreenKeyboard()

  return (
    <div className={styles.screenBody} {...keyboard}>
      <AnimatePresence initial={false} custom={navigation.back}>
        <motion.div
          key={navigation.navigationId}
          className={styles.screenPage}
          custom={navigation.back}
          variants={slide}
          initial="enter"
          animate="center"
          exit="exit"
          transition={
            reduceMotion
              ? { duration: 0 }
              : { duration: 0.24, ease: EASE_IN_OUT_SINE }
          }
        >
          {view === "list" && (
            <MenuList
              items={items}
              selectedIndex={navigation.selectedIndex}
              idPrefix={`${titleId}-${navigation.navigationId}`}
              labelledBy={titleId}
              shouldFocus={navigation.shouldFocus}
              restoredScrollTop={navigation.restoredScrollTop}
              listRef={registerList}
            />
          )}
          {view === "now-playing" && (
            <NowPlaying
              labelledBy={titleId}
              shouldFocus={navigation.shouldFocus}
            />
          )}
          {view === "brick" && <BrickGame />}
        </motion.div>
      </AnimatePresence>
    </div>
  )
}

import { useAtomValue } from "jotai"

import styles from "../ipod-classic.module.css"
import {
  brickStatusAtom,
  playbackAtom,
  titleAtom,
  viewAtom,
} from "../lib/atoms"
import { PauseIcon, PlayIcon } from "./icons"

export function TitleBar({ id }: { id: string }) {
  const title = useAtomValue(titleAtom)
  const view = useAtomValue(viewAtom)
  const brick = useAtomValue(brickStatusAtom)
  const { hasLoadedItem, isPlaying } = useAtomValue(playbackAtom)

  return (
    <div id={id} className={styles.titleBar}>
      {hasLoadedItem &&
        (isPlaying ? (
          <PlayIcon className={styles.playIcon} />
        ) : (
          <PauseIcon className={styles.playIcon} data-paused="" />
        ))}
      <div className={styles.battery} aria-hidden />
      {/* Brick swaps the title for balls left and score. */}
      {view === "brick" ? (
        <div className={`${styles.title} ${styles.brickTitle}`} dir="ltr">
          <span>{brick.balls}</span>
          <span>{brick.score}</span>
        </div>
      ) : (
        <div className={styles.title} dir="auto">
          {title}
        </div>
      )}
    </div>
  )
}

import { useRef, type KeyboardEvent } from "react"
import { useStore } from "jotai"

import { wheelSpeed } from "../lib/acceleration"
import { engineAtom, isInertAtom, viewAtom } from "../lib/atoms"
import { KEY_ARROW_STEP_DEGREES } from "../lib/constants"

const SCREEN_KEYS = new Set([
  "ArrowDown",
  "ArrowUp",
  "ArrowRight",
  "ArrowLeft",
  "Enter",
  " ",
  "Escape",
])

const SLIDER_KEYS = new Set([
  "ArrowDown",
  "ArrowUp",
  "ArrowRight",
  "ArrowLeft",
  "Home",
  "End",
  "PageUp",
  "PageDown",
])

/** Key repeat never counts as a fast spin, so arrows move one row. */
const MAX_ARROW_SPEED = 180

function consume(event: KeyboardEvent) {
  event.preventDefault()
  event.stopPropagation()
}

/**
 * Keys while a list or Now Playing has focus: arrows move, Enter and Space
 * select, Escape goes back when released.
 */
export function useScreenKeyboard() {
  const store = useStore()
  const stateRef = useRef<{ isEscapeDown: boolean; lastArrowTime?: number }>({
    isEscapeDown: false,
  })

  function onKeyDown(event: KeyboardEvent<HTMLElement>) {
    const engine = store.get(engineAtom)
    const view = store.get(viewAtom)
    if (!engine || view === "brick") return

    if (store.get(isInertAtom)) {
      if (SCREEN_KEYS.has(event.key) || SLIDER_KEYS.has(event.key)) {
        consume(event)
      }
      return
    }

    // Sliders and the song link keep their own keys on Now Playing.
    if (view === "now-playing" && event.key !== "Escape") {
      const { target } = event
      const isNative =
        (target instanceof HTMLInputElement && SLIDER_KEYS.has(event.key)) ||
        (target instanceof HTMLAnchorElement && event.key === "Enter")
      if (isNative) event.stopPropagation()
      else if (SCREEN_KEYS.has(event.key)) consume(event)
      return
    }

    const state = stateRef.current
    switch (event.key) {
      case "ArrowDown":
      case "ArrowUp": {
        consume(event)
        const direction = event.key === "ArrowDown" ? 1 : -1
        const elapsed =
          state.lastArrowTime === undefined
            ? 0
            : event.timeStamp - state.lastArrowTime
        state.lastArrowTime = event.timeStamp
        const speed = Math.min(
          wheelSpeed(KEY_ARROW_STEP_DEGREES, elapsed),
          MAX_ARROW_SPEED
        )
        engine.menu.move(direction, engine.menu.accelerate(speed, direction))
        break
      }
      case "ArrowLeft":
      case "ArrowRight":
        consume(event)
        break
      case "Enter":
      case " ":
        consume(event)
        if (!event.repeat) engine.wheel.select()
        break
      case "Escape":
        consume(event)
        if (!event.repeat) state.isEscapeDown = true
        break
    }
  }

  function onKeyUp(event: KeyboardEvent<HTMLElement>) {
    const state = stateRef.current
    if (event.key !== "Escape" || !state.isEscapeDown) return
    state.isEscapeDown = false
    store.get(engineAtom)?.wheel.menu()
  }

  function onBlur() {
    stateRef.current.isEscapeDown = false
  }

  return { onKeyDown, onKeyUp, onBlur }
}

/*
 * Dimensions are the device's own pixels; the whole iPod scales down through
 * --ipod-scale on narrow containers.
 */

.root {
  /* Outlines of the body, screen and wheel. */
  --ipod-line: var(--muted-foreground);
  /* Text, bars and the selected row on the screen. */
  --ipod-ink: var(--foreground);
  /* Labels on the wheel. */
  --ipod-icon: var(--muted-foreground);
  display: block;
  container-type: inline-size;
  container-name: ipod;
  font-family: var(--font-chicago-kare), Krungthep, system-ui, sans-serif;
  -webkit-text-size-adjust: 100%;
  text-size-adjust: 100%;
  -webkit-user-select: none;
  user-select: none;
  -webkit-touch-callout: none;
}

@media (prefers-contrast: more) {
  .root {
    --ipod-line: var(--foreground);
    --ipod-icon: var(--foreground);
  }
}

:where(.root) *,
:where(.root) *::before,
:where(.root) *::after {
  box-sizing: border-box;
}

:where(.root) :where(ul, li, p, button) {
  margin: 0;
  padding: 0;
}

:where(.root) :where(ul) {
  list-style-type: none;
}

:where(.root) :where(button) {
  background: none;
  border: 0;
  color: inherit;
  cursor: pointer;
  font: inherit;
  line-height: inherit;
}

:where(.root) :where(svg) {
  pointer-events: none;
}

.ipod {
  --ipod-scale: 1;
  position: relative;
  display: flex;
  justify-content: center;
  width: 100%;
  /* The 415px body stays laid out at full width while scaled down. */
  overflow-x: clip;
}

@container ipod (width < 440px) {
  .ipod {
    --ipod-scale: 0.9;
  }
}

@container ipod (width < 400px) {
  .ipod {
    --ipod-scale: 0.8;
  }
}

@container ipod (width < 360px) {
  .ipod {
    --ipod-scale: 0.75;
  }
}

.shadow {
  position: relative;
  flex: none;
  width: 415px;
  /* `scale` does not shrink layout, so the height follows it by hand. */
  height: calc(692px * var(--ipod-scale));
}

.shadowInner {
  position: relative;
  width: 100%;
  margin: 0 auto;
  transform-origin: top;
  transition: scale 0.25s ease-in-out;
  scale: var(--ipod-scale);
}

.body {
  position: relative;
  width: 415px;
  height: 692px;
  background: var(--background);
  border: 1px solid var(--ipod-line);
  border-radius: 38px;
}

/* Screen */

.screen {
  position: relative;
  box-sizing: content-box;
  width: 273px;
  height: 223px;
  margin: 30px auto 0;
  padding: 7px;
  font-size: 26px;
  line-height: 1;
  color: var(--ipod-ink);
  border: 1px solid var(--ipod-line);
  border-radius: 10px;
  pointer-events: none;
}

.menuLayer {
  width: 100%;
  height: 100%;
}

.menuLayer[data-hidden] {
  visibility: hidden;
}

.visuallyHidden {
  position: absolute;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
}

.menu {
  position: relative;
  z-index: 2;
  display: flex;
  flex-direction: column;
  width: 100%;
  height: 100%;
}

.screenBody {
  position: relative;
  flex: none;
  height: 181.7px;
  overflow: clip;
}

.screenPage {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
}

/* Title bar */

.titleBar {
  position: relative;
  flex: none;
  height: 37px;
  margin: 0 5px;
  text-align: center;
  border-bottom: 1px solid var(--ipod-line);
}

.title {
  position: absolute;
  top: calc(50% + 3px);
  left: 50%;
  max-width: calc(100% - 86px);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  transform: translate(-50%, -50%);
}

.brickTitle {
  display: grid;
  grid-template-columns: 1fr 1fr;
  width: calc(100% - 110px);
  max-width: calc(100% - 110px);
  overflow: visible;
}

.brickTitle > :first-child {
  justify-self: start;
}

.brickTitle > :last-child {
  justify-self: end;
}

.playIcon {
  position: absolute;
  top: 50%;
  inset-inline-start: 10px;
  display: inline-block;
  width: auto;
  height: 20px;
  fill: var(--ipod-ink);
  transform: translate(0, calc(-50% + 1.2px)) scale(0.9);
}

.playIcon[data-paused] {
  transform: translate(2.3px, calc(-50% + 1.2px)) scale(1, 0.8);
}

/* Drawn at 3.3x and scaled down so the 2px strokes stay crisp. */
.battery {
  position: absolute;
  top: 3px;
  inset-inline-end: 5px;
  box-sizing: content-box;
  width: 98px;
  height: 44px;
  background:
    linear-gradient(var(--ipod-ink), var(--ipod-ink)) right 0 top -6px / 6px
      calc((100% - 28%) / 2 + 6px) no-repeat,
    linear-gradient(var(--ipod-ink), var(--ipod-ink)) right 0 bottom -6px / 6px
      calc((100% - 28%) / 2 + 6px) no-repeat;
  border: 6px solid var(--ipod-ink);
  border-right: 0;
  transform: scale(0.3, 0.3);
  transform-origin: 100% 23%;
}

.battery::before {
  content: "";
  position: absolute;
  top: 50%;
  right: -6px;
  width: 6px;
  height: 28%;
  border-top: 6px solid var(--ipod-ink);
  border-right: 6px solid var(--ipod-ink);
  border-bottom: 6px solid var(--ipod-ink);
  transform: translate(0, -50%);
}

.battery::after {
  content: "";
  position: absolute;
  top: 5px;
  bottom: 5px;
  left: 5px;
  width: 84px;
  background: repeating-linear-gradient(
    to right,
    var(--ipod-ink),
    var(--ipod-ink) 16px,
    transparent 16px,
    transparent 22px,
    var(--ipod-ink) 22px,
    var(--ipod-ink) 37px,
    transparent 38px,
    transparent 43px,
    var(--ipod-ink) 42px,
    var(--ipod-ink) 57px,
    transparent 59px,
    transparent 64px,
    var(--ipod-ink) 55px,
    var(--ipod-ink) 55px
  );
}

/* Menu list */

.menuItems {
  /* Rows measure their offset against the list. */
  position: relative;
  height: 180px;
  margin: 1.7px 0 0;
  padding: 0 5px;
  overflow: hidden auto;
  /*
   * The site sets these on every element, and any value but `auto` makes
   * Chrome ignore ::-webkit-scrollbar, leaving a thin overlay scrollbar.
   */
  scrollbar-width: auto;
  scrollbar-color: auto;
}

/* Firefox has no ::-webkit-scrollbar; the closest is ink on the page. */
@supports not selector(::-webkit-scrollbar) {
  .menuItems {
    scrollbar-color: var(--ipod-ink) transparent;
  }
}

.menuItems::-webkit-scrollbar {
  width: 12px;
}

.menuItems::-webkit-scrollbar-track {
  border: 1px solid var(--ipod-line);
}

.menuItems::-webkit-scrollbar-thumb {
  background-color: var(--ipod-ink);
  background-clip: padding-box;
  border: 2px solid transparent;
}

.menuItem {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 3px 12px 1px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.menuItem[data-centered] {
  justify-content: center;
}

.menuItem[data-selected]:not([data-action="info"]) {
  color: var(--background);
  background-color: var(--ipod-ink);
}

.itemTitle {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.itemValue {
  font-weight: normal;
  white-space: nowrap;
}

.menuItem[data-action="inline-toggle"] .itemValue {
  overflow: hidden;
  text-overflow: ellipsis;
}

.chevron {
  display: inline-block;
  flex: none;
  width: 12px;
  height: 12px;
  margin-inline-end: 5px;
  border-block-start: 3px solid currentcolor;
  border-inline-end: 3px solid currentcolor;
  transform: rotate(45deg) translateY(-2px);
}

/* Now Playing */

.nowPlaying {
  display: flex;
  flex-direction: column;
  height: 180px;
  margin-top: 1.7px;
  padding: 4px 15px 7px;
  overflow: clip;
}

.nowPlayingIndex {
  display: grid;
  grid-template-columns: 1fr auto;
  align-items: center;
  margin-bottom: 6px;
  font-size: 20px;
  line-height: 1;
  text-align: left;
}

.playModifier {
  display: flex;
  align-items: center;
  gap: 6px;
  fill: var(--ipod-ink);
}

.nowPlayingInfo {
  margin-bottom: 5px;
  text-align: center;
}

.songTitle {
  margin-bottom: 2px;
}

.songTitleLink {
  display: block;
  color: inherit;
  text-decoration: none;
  pointer-events: auto;
}

.songTitleLink:hover,
.songTitleLink:focus-visible {
  text-decoration: underline;
}

.artist,
.album {
  margin-bottom: 2px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* Two panes side by side; scrubbing or volume slides the second in. */
.progressPanes {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 30px;
  align-items: center;
  width: calc(200% + 30px);
  margin-top: auto;
  transition: transform 0.3s ease-out;
}

.progressPanes[data-mode="volume"],
.progressPanes[data-mode="scrubbing"] {
  transform: translateX(calc(-50% - 15px));
}

@media (prefers-reduced-motion: reduce) {
  .progressPanes {
    transition: none;
  }
}

.timeAndProgress,
.scrubber {
  padding-top: 10px;
}

.scrubber,
.volume {
  grid-area: 1 / 2;
}

.scrubber[data-inactive],
.volume[data-inactive] {
  opacity: 0;
}

.progressLabels {
  display: flex;
  justify-content: space-between;
  margin-top: 6px;
  font-size: 26px;
  font-feature-settings: "tnum";
  font-variant-numeric: tabular-nums;
}

.volume {
  display: grid;
  grid-template-columns: auto 1fr auto;
  gap: 7px;
  align-items: center;
  fill: var(--ipod-ink);
}

.progressBar {
  position: relative;
  width: 100%;
  height: 15px;
  min-height: 12px;
  overflow: hidden;
  border: 1px solid var(--ipod-ink);
  border-radius: 7px;
}

.progressBar:has(.progressMarker) {
  overflow: visible;
}

.progressBar:has(.rangeInput:focus-visible) {
  outline: 2px solid currentcolor;
  outline-offset: 2px;
}

.progressFill {
  width: 0%;
  height: 15px;
  background: var(--ipod-ink);
}

.progressMarker {
  position: absolute;
  top: 50%;
  width: 10px;
  height: 10px;
  background: var(--ipod-ink);
  transform: translate(-50%, -50%) rotate(45deg);
}

.rangeInput {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  margin: 0;
  opacity: 0;
}

/* Marquee */

.marquee {
  overflow: hidden;
}

.marqueeTrack {
  --marquee-distance: calc(var(--marquee-copy-width, 0) + 30);
  display: flex;
  gap: 30px;
  width: max-content;
  margin-inline: auto;
}

.marquee[data-scrolling] .marqueeTrack {
  animation: marquee-scroll calc(var(--marquee-distance) * 0.05s) linear 2s
    infinite;
}

.marqueeCopy {
  white-space: nowrap;
}

@keyframes marquee-scroll {
  to {
    transform: translateX(calc(var(--marquee-distance) * -1px));
  }
}

@media (prefers-reduced-motion: reduce) {
  .marqueeTrack {
    display: block;
    width: auto;
  }

  .marquee[data-scrolling] .marqueeTrack {
    animation: none;
  }

  .marqueeCopy {
    display: block;
    max-width: 100%;
    overflow: hidden;
    text-overflow: ellipsis;
  }

  .marqueeCopy[aria-hidden] {
    display: none;
  }
}

/* Brick */

.brickScreen {
  height: 180px;
  margin-top: 1.7px;
  padding: 0 5px;
}

.brickCanvas {
  display: block;
  width: 100%;
  color: var(--ipod-ink);
  image-rendering: pixelated;
}

/* Boot and error overlays */

.overlay {
  position: absolute;
  inset: 0;
  z-index: 3;
  display: flex;
  align-items: center;
  justify-content: center;
  pointer-events: none;
}

.bootLogo {
  width: 72px;
  height: 90px;
  fill: currentcolor;
  transform: translateY(-10px);
}

.sadIpod {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 8px;
}

.sadIpodIcon {
  width: 90px;
  height: 90px;
  background-color: currentcolor;
  transform: translateX(-10%);
  mask: var(--mask) center / contain no-repeat;
}

.errorMessage {
  position: absolute;
  bottom: 20px;
  margin: 0 10px;
  font-size: 13px;
  text-align: center;
}

/* Click wheel */

.clickWheel {
  position: relative;
  top: 30px;
  width: 350px;
  height: 350px;
  margin: 0 auto;
  border: 1px solid var(--ipod-line);
  border-radius: 50%;
  cursor: pointer;
  touch-action: none;
  -webkit-user-select: none;
  user-select: none;
  -webkit-touch-callout: none;
}

.clickWheel[data-dragging] .wheelButton,
.clickWheel[data-dragging] .selectButton {
  pointer-events: none;
}

.wheelButton {
  position: absolute;
  inset: 0;
  display: flex;
  border-radius: 50%;
  touch-action: manipulation;
  -webkit-tap-highlight-color: transparent;
}

.wheelButton svg {
  fill: var(--ipod-icon);
  transition: scale 0.15s ease-out;
}

.wheelButton:active svg {
  scale: 0.97;
}

.menuButton {
  align-items: flex-start;
  justify-content: center;
  padding-top: 9.5px;
  clip-path: polygon(50% 50%, 0% 0%, 100% 0%);
}

.menuButton svg {
  width: 136px;
  height: auto;
}

.menuButton text {
  font-family: Arial, sans-serif;
  font-size: 55px;
  font-weight: bold;
  fill: var(--ipod-icon);
}

.menuButton path {
  fill: transparent;
}

.backButton {
  align-items: center;
  justify-content: flex-start;
  padding-left: 6px;
  clip-path: polygon(50% 50%, 0% 0%, 0% 100%);
}

.backButton svg {
  rotate: 180deg;
}

.forwardButton {
  align-items: center;
  justify-content: flex-end;
  padding-right: 6px;
  clip-path: polygon(50% 50%, 100% 0%, 100% 100%);
}

.playPauseButton {
  align-items: flex-end;
  justify-content: center;
  padding-bottom: 12px;
  clip-path: polygon(50% 50%, 0% 100%, 100% 100%);
}

/* Two diameters; the scroll ring covers their middle, leaving four dividers. */
/* Clipped to the wheel's outer edge, so all four ends sit flush with it. */
.wheelDividers {
  position: absolute;
  inset: -1px;
  overflow: hidden;
  border-radius: 50%;
  pointer-events: none;
}

.wheelDividers::before,
.wheelDividers::after {
  content: "";
  position: absolute;
  top: 0;
  /* Centers the 1px line, so it turns about the wheel's true center. */
  left: calc(50% - 0.5px);
  height: 100%;
  border-left: 1px solid var(--ipod-line);
}

.wheelDividers::before {
  transform: rotate(135deg);
}

.wheelDividers::after {
  transform: rotate(45deg);
}

.scrollWheel {
  position: absolute;
  top: 50%;
  left: 50%;
  z-index: 1;
  width: var(--scroll-wheel-pct);
  height: var(--scroll-wheel-pct);
  background: var(--background);
  border: 1px solid var(--ipod-line);
  border-radius: 50%;
  cursor: pointer;
  touch-action: none;
  transform: translate(-50%, -50%);
  -webkit-user-select: none;
  user-select: none;
  -webkit-touch-callout: none;
}

.scrollWheel:focus {
  outline: none;
}

.selectButton {
  position: absolute;
  top: 50%;
  left: 50%;
  z-index: 1;
  width: var(--select-button-pct);
  height: var(--select-button-pct);
  background: var(--background);
  border: 1px solid var(--ipod-line);
  border-radius: 50%;
  touch-action: manipulation;
  transform: translate(-50%, -50%);
  transition: background-color 0.1s ease-out;
  -webkit-tap-highlight-color: transparent;
}

.selectButton:active {
  background: var(--accent);
}

"use client"

// Recreated from the iPod in Apple Music's web app (its 404 page): https://music.apple.com
import {
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
  type ComponentProps,
} from "react"
import { createStore, Provider, useAtomValue } from "jotai"

import { cn } from "@/lib/utils"

import { ClickWheel } from "./components/click-wheel"
import { Screen } from "./components/screen"
import styles from "./ipod-classic.module.css"
import { catalogAtom, engineAtom, type IpodStore } from "./lib/atoms"
import { createCatalog } from "./lib/catalog"
import { createIpodEngine } from "./lib/engine"
import type { IpodLibrary } from "./lib/types"

export type IpodClassicProps = ComponentProps<"div"> & {
  /**
   * Songs and playlists to browse and play.
   * @fumadocsHref #ipodlibrary
   */
  library: IpodLibrary
}

export function IpodClassic({
  library,
  className,
  ...props
}: IpodClassicProps) {
  const catalog = useMemo(() => createCatalog(library), [library])
  const [store] = useState(() => {
    const ipodStore = createStore()
    ipodStore.set(catalogAtom, catalog)
    return ipodStore
  })

  useEffect(() => {
    store.set(catalogAtom, catalog)
  }, [store, catalog])

  return (
    <Provider store={store}>
      <div {...props} className={cn(styles.root, className)}>
        <IpodBody store={store} />
      </div>
    </Provider>
  )
}

function IpodBody({ store }: { store: IpodStore }) {
  const engine = useAtomValue(engineAtom)
  const menuRef = useRef<HTMLDivElement>(null)
  const listRef = useRef<HTMLUListElement | null>(null)

  // An outgoing list unmounts after the new one mounts, so it only clears itself.
  const registerList = useCallback((element: HTMLUListElement) => {
    listRef.current = element
    return () => {
      if (listRef.current === element) listRef.current = null
    }
  }, [])

  // The engine needs an AudioContext, so it only exists on the client.
  useEffect(() => {
    const created = createIpodEngine({
      store,
      getMenuElement: () => menuRef.current,
      getListElement: () => listRef.current,
    })
    store.set(engineAtom, created)
    return () => {
      store.set(engineAtom, null)
      created.destroy()
    }
  }, [store])

  return (
    <div className={styles.ipod}>
      <div className={styles.shadow}>
        <div className={styles.shadowInner}>
          <div
            className={styles.body}
            onPointerDown={engine?.handleUserActivity}
            onKeyDownCapture={(event) =>
              engine?.handleKeyActivity(event.nativeEvent)
            }
          >
            <Screen menuRef={menuRef} registerList={registerList} />
            <ClickWheel />
          </div>
        </div>
      </div>
    </div>
  )
}

import {
  ACCELERATION_STALE_MS,
  MAX_SMOOTHED_SPEED,
  SPEED_SMOOTHING,
  type Acceleration,
} from "./constants"

/** Degrees per second. */
export function wheelSpeed(degrees: number, elapsedMs: number) {
  return elapsedMs > 0 ? (degrees / elapsedMs) * 1000 : 0
}

export function tierFor(config: Acceleration, heldMs: number) {
  const index = Math.min(
    config.tiers.length - 1,
    Math.floor(heldMs / config.tierMs)
  )
  return config.tiers[index]
}

/**
 * Turns a steady fast spin into bigger steps, climbing a tier every
 * `tierMs` while the smoothed speed stays above `minSpeed`.
 */
export function createAccelerator(config: Acceleration) {
  let smoothed = 0
  let lastDirection: number | undefined
  let lastTime: number | undefined
  let fastSince: number | undefined

  function reset() {
    smoothed = 0
    lastDirection = undefined
    lastTime = undefined
    fastSince = undefined
  }

  function next(speed: number, direction: number, active: boolean) {
    if (!active) {
      reset()
      return config.tiers[0]
    }
    const now = performance.now()
    const isStale =
      lastTime !== undefined && now - lastTime > ACCELERATION_STALE_MS
    lastTime = now
    const clamped = Math.min(speed, MAX_SMOOTHED_SPEED)

    if (direction !== lastDirection || isStale) {
      smoothed = clamped
      lastDirection = direction
      fastSince = undefined
    } else {
      smoothed += SPEED_SMOOTHING * (clamped - smoothed)
    }

    if (smoothed <= config.minSpeed) {
      fastSince = undefined
      return config.tiers[0]
    }
    fastSince ??= now
    return tierFor(config, now - fastSince)
  }

  return { next, reset }
}

