import { atom, type createStore } from "jotai"
import { atomWithStorage, createJSONStorage } from "jotai/utils"

import { INITIAL_BRICK_STATUS, type BrickStatus } from "./brick-engine"
import { createCatalog } from "./catalog"
import type { IpodEngine } from "./engine"
import {
  getScreen,
  screenItems,
  screenTitle,
  type MenuContext,
  type Screen,
} from "./menu"
import type { IpodCatalog, IpodSettings, IpodSong, ScrollTarget } from "./types"

/** Each iPod owns a store, so two on a page never share a screen. */
export type IpodStore = ReturnType<typeof createStore>

export const DEFAULT_SETTINGS: IpodSettings = {
  shuffle: "off",
  repeat: "off",
  clicker: "on",
  volume: 50,
}

const SETTING_VALUES = {
  shuffle: ["off", "songs"],
  repeat: ["off", "one", "all"],
  clicker: ["off", "on"],
} as const

/** Falls back per field, so one bad value does not wipe the rest. */
function parseSettings(raw: unknown): IpodSettings {
  const value = (raw ?? {}) as Record<string, unknown>
  const pick = <T extends string>(values: readonly T[], input: unknown) =>
    values.includes(input as T) ? (input as T) : undefined
  const volume = value.volume
  return {
    shuffle:
      pick(SETTING_VALUES.shuffle, value.shuffle) ?? DEFAULT_SETTINGS.shuffle,
    repeat:
      pick(SETTING_VALUES.repeat, value.repeat) ?? DEFAULT_SETTINGS.repeat,
    clicker:
      pick(SETTING_VALUES.clicker, value.clicker) ?? DEFAULT_SETTINGS.clicker,
    volume:
      typeof volume === "number" && volume >= 0 && volume <= 100
        ? volume
        : DEFAULT_SETTINGS.volume,
  }
}

const settingsStorage = createJSONStorage<IpodSettings>(() => localStorage)

export const settingsAtom = atomWithStorage(
  "ipod-classic:settings",
  DEFAULT_SETTINGS,
  {
    ...settingsStorage,
    getItem: (key, initialValue) =>
      parseSettings(settingsStorage.getItem(key, initialValue)),
  }
)

export const catalogAtom = atom<IpodCatalog>(
  createCatalog({ songs: [], playlists: [] })
)

export const statusAtom = atom({ isBooting: true, isOnline: true })

/** Booting or offline: the screen shows an overlay and input is ignored. */
export const isInertAtom = atom((get) => {
  const { isBooting, isOnline } = get(statusAtom)
  return isBooting || !isOnline
})

export type PlaybackState = {
  isPlaying: boolean
  currentTime: number
  duration: number
  /** Index into `queue`, which keeps list order even when shuffled. */
  currentTrackIndex: number
  /** Position in play order, which differs from the queue when shuffled. */
  queuePosition: number
  queue: IpodSong[]
  hasLoadedItem: boolean
  isLoading: boolean
  /** 0 to 1. */
  volume: number
}

export const playbackAtom = atom<PlaybackState>({
  isPlaying: false,
  currentTime: 0,
  duration: 0,
  currentTrackIndex: 0,
  queuePosition: 0,
  queue: [],
  hasLoadedItem: false,
  isLoading: false,
  volume: DEFAULT_SETTINGS.volume / 100,
})

export const hasQueueAtom = atom((get) => get(playbackAtom).queue.length > 0)

export type StackEntry = Screen & {
  selectedItemId?: string
  selectedIndexAtPush?: number
  scrollTopAtPush?: number
  /** An idle jump was not the user's choice, so going back keeps their row. */
  suppressSyncAtPush?: boolean
}

export type NavigationState = {
  stack: StackEntry[]
  selectedIndex: number
  /** Changes on every push and pop, keying the sliding screen. */
  navigationId: number
  back: boolean
  shouldFocus: boolean
  restoredScrollTop: number | undefined
}

export const navigationAtom = atom<NavigationState>({
  stack: [{ key: "main" }],
  selectedIndex: 0,
  navigationId: 0,
  back: false,
  shouldFocus: false,
  restoredScrollTop: undefined,
})

export const screenAtom = atom((get) => get(navigationAtom).stack.at(-1)!)

export const viewAtom = atom((get) => getScreen(get(screenAtom).key).view)

export const titleAtom = atom((get) =>
  screenTitle(get(screenAtom), get(catalogAtom))
)

export const menuContextAtom = atom<MenuContext>((get) => ({
  catalog: get(catalogAtom),
  hasNowPlaying: get(hasQueueAtom),
}))

export const itemsAtom = atom((get) =>
  screenItems(get(screenAtom), get(menuContextAtom))
)

/** How long Select must be held on this screen, if holding does anything. */
export const selectHoldMsAtom = atom(
  (get) => getScreen(get(screenAtom).key).selectHold?.ms ?? null
)

export const seekAtom = atom<{ isSeeking: boolean; previewTime?: number }>({
  isSeeking: false,
})

export const isAdjustingVolumeAtom = atom(false)

/** What turning the wheel changes right now. */
export const scrollTargetAtom = atom<ScrollTarget>((get) => {
  if (get(seekAtom).isSeeking) return "seek"
  const view = get(viewAtom)
  return view === "now-playing" ? "volume" : view
})

export const brickStatusAtom = atom<BrickStatus>(INITIAL_BRICK_STATUS)

/** Set once the client has an AudioContext; null on the server. */
export const engineAtom = atom<IpodEngine | null>(null)

/** The playfield, in LCD pixels. */
export const FIELD_WIDTH = 148
export const FIELD_HEIGHT = 101

const PADDLE_WIDTH = 30
const PADDLE_HEIGHT = 4
const BALL_RADIUS = 1.5
const BRICK_HEIGHT = 4
const BRICKS_PER_ROW = 12
const BRICK_GAP = 2
const ROW_GAP = 4
const SIDE_MARGIN = 3
const TOP_MARGIN = 3
const BRICK_WIDTH =
  (FIELD_WIDTH - SIDE_MARGIN * 2 - (BRICKS_PER_ROW - 1) * BRICK_GAP) /
  BRICKS_PER_ROW
const FIRST_LEVEL_ROWS = 2
const MAX_ROWS = 5
const STARTING_BALLS = 3
const SERVE_DELAY_MS = 1000
const BASE_TICK_MS = 40
const SPEEDUP_PER_LEVEL = 0.1
const MAX_SPEEDUP = 1.5
const BALL_COMPONENT_SPEED = 1.7
const BALL_SPEED = Math.hypot(BALL_COMPONENT_SPEED, BALL_COMPONENT_SPEED)
/** Edge hits come off faster... */
const EDGE_SPEED_BOOST = 0.25
/** ...and at a steeper angle. */
const EDGE_ANGLE = 0.8
const PADDLE_TRAVEL = FIELD_WIDTH - PADDLE_WIDTH
const PADDLE_TOP = FIELD_HEIGHT - PADDLE_HEIGHT

const clamp = (value: number, min: number, max: number) =>
  Math.min(Math.max(value, min), max)

export function tickMs(level: number) {
  return (
    BASE_TICK_MS / Math.min(1 + (level - 1) * SPEEDUP_PER_LEVEL, MAX_SPEEDUP)
  )
}

type Brick = { x: number; y: number; destroyed: boolean }

function createBricks(level: number) {
  const rows = Math.min(FIRST_LEVEL_ROWS + level - 1, MAX_ROWS)
  const bricks: Brick[] = []
  for (let row = 0; row < rows; row += 1) {
    for (let column = 0; column < BRICKS_PER_ROW; column += 1) {
      bricks.push({
        x: SIDE_MARGIN + column * (BRICK_WIDTH + BRICK_GAP),
        y: TOP_MARGIN + row * (BRICK_HEIGHT + ROW_GAP),
        destroyed: false,
      })
    }
  }
  return bricks
}

const serveBall = () => ({
  x: BALL_RADIUS,
  y: FIELD_HEIGHT / 2,
  dx: BALL_COMPONENT_SPEED,
  dy: BALL_COMPONENT_SPEED,
})

function initialState() {
  return {
    paddleX: PADDLE_TRAVEL / 2,
    ball: serveBall(),
    isBallInPlay: false,
    serveTicks: 0,
    bricks: createBricks(1),
    score: 0,
    balls: STARTING_BALLS,
    level: 1,
    isGameOver: false,
  }
}

type BrickState = ReturnType<typeof initialState>

/** What the title bar and the screen reader announce. */
export type BrickStatus = {
  score: number
  balls: number
  message: string
}

const LAUNCH_MESSAGE = "Press Center to Launch Ball"

export const INITIAL_BRICK_STATUS: BrickStatus = {
  score: 0,
  balls: STARTING_BALLS,
  message: LAUNCH_MESSAGE,
}

export function brickStatus(state: BrickState): BrickStatus {
  let message = LAUNCH_MESSAGE
  if (state.isGameOver) message = "GAME OVER"
  else if (state.isBallInPlay || state.serveTicks > 0) message = ""
  return { score: state.score, balls: state.balls, message }
}

export function createBrickGame() {
  const state = initialState()

  function serve() {
    state.ball = serveBall()
    state.isBallInPlay = false
    state.serveTicks = Math.round(SERVE_DELAY_MS / tickMs(state.level))
  }

  function loseBall() {
    state.balls -= 1
    if (state.balls > 0) {
      serve()
      return
    }
    state.isBallInPlay = false
    state.isGameOver = true
  }

  function nextLevel() {
    state.level += 1
    state.bricks = createBricks(state.level)
    serve()
  }

  /** Where the ball lands on the paddle sets its angle and speed. */
  function bounceOffPaddle() {
    const { ball } = state
    const half = PADDLE_WIDTH / 2
    const offset = clamp((ball.x - (state.paddleX + half)) / half, -1, 1)
    const speed = BALL_SPEED * (1 + Math.abs(offset) * EDGE_SPEED_BOOST)
    const x = offset * EDGE_ANGLE
    const length = Math.hypot(x, 1)
    ball.dx = (x / length) * speed
    ball.dy = -speed / length
  }

  function hitSide(index: number): "side" | "face" | null {
    const { ball, bricks } = state
    const { x, y, destroyed } = bricks[index]
    const neighbor = index - Math.sign(ball.dx)
    if (
      destroyed ||
      ball.x + BALL_RADIUS < x ||
      ball.x - BALL_RADIUS > x + BRICK_WIDTH ||
      ball.y + BALL_RADIUS < y ||
      ball.y - BALL_RADIUS > y + BRICK_HEIGHT
    ) {
      return null
    }
    const overlapX =
      ball.dx > 0
        ? ball.x + BALL_RADIUS - x
        : x + BRICK_WIDTH - ball.x + BALL_RADIUS
    const overlapY =
      ball.dy > 0
        ? ball.y + BALL_RADIUS - y
        : y + BRICK_HEIGHT - ball.y + BALL_RADIUS
    // A side hit is impossible when a live brick sits right beside it.
    const hasNeighbor =
      Math.floor(neighbor / BRICKS_PER_ROW) ===
        Math.floor(index / BRICKS_PER_ROW) &&
      bricks[neighbor]?.destroyed === false

    if (
      !hasNeighbor &&
      overlapX * Math.abs(ball.dy) < overlapY * Math.abs(ball.dx)
    ) {
      return (x + BRICK_WIDTH / 2 - ball.x) * ball.dx > 0 ? "side" : null
    }
    return (y + BRICK_HEIGHT / 2 - ball.y) * ball.dy > 0 ? "face" : null
  }

  function collideBricks() {
    const { ball } = state
    for (const [index, brick] of state.bricks.entries()) {
      const hit = hitSide(index)
      if (!hit) continue
      brick.destroyed = true
      state.score += 1
      if (hit === "face") ball.dy = -ball.dy
      else ball.dx = -ball.dx
      return true
    }
    return false
  }

  function tick() {
    const { ball } = state
    if (state.serveTicks > 0) {
      state.serveTicks -= 1
      state.isBallInPlay = state.serveTicks === 0
    }
    if (!state.isBallInPlay) return

    const wasAbovePaddle = ball.y + BALL_RADIUS < PADDLE_TOP
    ball.x += ball.dx
    ball.y += ball.dy
    if (
      (ball.x <= BALL_RADIUS && ball.dx < 0) ||
      (ball.x >= FIELD_WIDTH - BALL_RADIUS && ball.dx > 0)
    ) {
      ball.dx = -ball.dx
    }
    if (ball.y <= BALL_RADIUS && ball.dy < 0) ball.dy = -ball.dy
    if (ball.y >= FIELD_HEIGHT) {
      loseBall()
      return
    }
    if (
      ball.dy > 0 &&
      wasAbovePaddle &&
      ball.y + BALL_RADIUS >= PADDLE_TOP &&
      ball.x + BALL_RADIUS >= state.paddleX &&
      ball.x - BALL_RADIUS <= state.paddleX + PADDLE_WIDTH
    ) {
      bounceOffPaddle()
    }
    if (collideBricks() && state.bricks.every((brick) => brick.destroyed)) {
      nextLevel()
    }
  }

  /** `fraction` of the paddle's full travel; a whole turn crosses the field. */
  function movePaddle(fraction: number) {
    if (state.isGameOver) return
    state.paddleX = clamp(
      state.paddleX + fraction * PADDLE_TRAVEL,
      0,
      PADDLE_TRAVEL
    )
  }

  function launchBall() {
    if (state.isGameOver) {
      Object.assign(state, initialState())
      return
    }
    state.isBallInPlay = true
    state.serveTicks = 0
  }

  return { state, tick, movePaddle, launchBall }
}

const INK = 1
const PADDLE_INK = 2

/** Pixels driven by `ink` light up per `drive`, with the LCD's smear. */
export function drawField(state: BrickState, drive: Uint8Array) {
  drive.fill(0)
  const fill = (
    x: number,
    y: number,
    width: number,
    height: number,
    value = INK
  ) => {
    const left = Math.max(Math.round(x), 0)
    const right = Math.min(Math.round(x) + width, FIELD_WIDTH)
    const bottom = Math.min(Math.round(y) + height, FIELD_HEIGHT)
    for (let row = Math.max(Math.round(y), 0); row < bottom; row += 1) {
      drive.fill(value, row * FIELD_WIDTH + left, row * FIELD_WIDTH + right)
    }
  }

  for (const brick of state.bricks) {
    if (!brick.destroyed) fill(brick.x, brick.y, BRICK_WIDTH, BRICK_HEIGHT)
  }
  fill(state.paddleX, PADDLE_TOP, PADDLE_WIDTH, PADDLE_HEIGHT, PADDLE_INK)
  fill(
    state.ball.x - BALL_RADIUS,
    state.ball.y - BALL_RADIUS,
    BALL_RADIUS * 2,
    BALL_RADIUS * 2
  )
}

const RISE_MS = 20
const FALL_MS = 70
/** The paddle clears faster so steering does not leave a long trail. */
const PADDLE_FALL_MS = 25
const SETTLED = 1 / 255

/**
 * Slow LCD crystals: each pixel eases toward its drive through two stages,
 * rising fast and fading slow, which leaves the ball a short ghost trail.
 */
export function createLcdInk(width: number, height: number) {
  const size = width * height
  const drive = new Uint8Array(size)
  const stage = new Float32Array(size)
  const ink = new Float32Array(size)
  const lastDrive = new Uint8Array(size)

  function fade(elapsedMs: number) {
    const rise = 1 - Math.exp(-elapsedMs / RISE_MS)
    const fall = 1 - Math.exp(-elapsedMs / FALL_MS)
    const paddleFall = 1 - Math.exp(-elapsedMs / PADDLE_FALL_MS)
    let changed = false

    for (let i = 0; i < size; i += 1) {
      const target = drive[i] === 0 ? 0 : 1
      lastDrive[i] = drive[i] || lastDrive[i]
      if (
        Math.abs(target - stage[i]) > SETTLED ||
        Math.abs(target - ink[i]) > SETTLED
      ) {
        const falloff = lastDrive[i] === PADDLE_INK ? paddleFall : fall
        const toStage = target - stage[i]
        stage[i] += toStage * (toStage > 0 ? rise : falloff)
        const toInk = stage[i] - ink[i]
        ink[i] += toInk * (toInk > 0 ? rise : falloff)
        changed = true
      } else {
        changed ||= stage[i] !== target || ink[i] !== target
        stage[i] = target
        ink[i] = target
      }
    }
    return changed
  }

  function settle() {
    for (let i = 0; i < size; i += 1) {
      lastDrive[i] = drive[i] || lastDrive[i]
      stage[i] = drive[i] === 0 ? 0 : 1
      ink[i] = stage[i]
    }
  }

  return { width, height, drive, ink, fade, settle }
}

type LcdInk = ReturnType<typeof createLcdInk>

/** Pixel edges dim to this, drawing the LCD's grid between cells. */
const GRID_SHADE = 0.7
const MIN_SCALE_FOR_GRID = 3

function gridShade(position: number, scale: number) {
  const edge = Math.round((position + 0.5) / scale) * scale
  return 1 - (1 - GRID_SHADE) * Math.max(0, 1 - Math.abs(position + 0.5 - edge))
}

/** Paints the ink buffer onto a canvas at device resolution. */
export function createLcdRenderer(canvas: HTMLCanvasElement, lcd: LcdInk) {
  const context = canvas.getContext("2d")
  let image: ImageData | undefined
  let sourceIndex = new Int32Array(0)
  let shade = new Float32Array(0)
  let resolution: MediaQueryList | undefined

  function buildMaps() {
    const { width, height } = canvas
    const scale = width / lcd.width
    const showGrid = scale > 1
    sourceIndex = new Int32Array(width * height)
    shade = new Float32Array(width * height)
    for (let y = 0; y < height; y += 1) {
      const row = Math.min(Math.floor((y + 0.5) / scale), lcd.height - 1)
      const rowShade = showGrid ? gridShade(y, scale) : 1
      for (let x = 0; x < width; x += 1) {
        const column = Math.floor((x + 0.5) / scale)
        const index = y * width + x
        sourceIndex[index] = row * lcd.width + column
        shade[index] = rowShade * (showGrid ? gridShade(x, scale) : 1) * 255
      }
    }
  }

  function paint() {
    if (!context || !image) return
    for (let i = 0; i < sourceIndex.length; i += 1) {
      image.data[i * 4 + 3] = lcd.ink[sourceIndex[i]] * shade[i]
    }
    context.putImageData(image, 0, 0)
  }

  function resize() {
    const style = getComputedStyle(canvas)
    const scale = Number(style.getPropertyValue("--ipod-scale")) || 1
    const deviceWidth = Math.round(
      canvas.clientWidth * scale * devicePixelRatio
    )
    const width =
      deviceWidth >= lcd.width * MIN_SCALE_FOR_GRID ? deviceWidth : lcd.width
    if (image && width === canvas.width) return

    canvas.width = width
    canvas.height = Math.round((width * lcd.height) / lcd.width)
    buildMaps()
    image = context?.createImageData(canvas.width, canvas.height)
    applyInk()
  }

  /** Ink is the canvas's CSS color, which follows the site theme. */
  function applyInk() {
    if (!context || !image) return
    // The canvas resolves any CSS color (e.g. oklch) to RGB for us.
    context.fillStyle = getComputedStyle(canvas).color
    context.fillRect(0, 0, 1, 1)
    const [r, g, b] = context.getImageData(0, 0, 1, 1).data
    for (let i = 0; i < image.data.length; i += 4) {
      image.data.set([r, g, b], i)
    }
    paint()
  }

  function watchResolution() {
    resolution?.removeEventListener("change", watchResolution)
    resolution = matchMedia(`(resolution: ${devicePixelRatio}dppx)`)
    resolution.addEventListener("change", watchResolution)
    resize()
  }

  // The iPod scales with its container, which a resize of either can change.
  const observer = new ResizeObserver(resize)
  observer.observe(document.documentElement)
  observer.observe(canvas)
  watchResolution()
  // Switching theme swaps the class on <html>.
  const themeObserver = new MutationObserver(applyInk)
  themeObserver.observe(document.documentElement, {
    attributes: true,
    attributeFilter: ["class"],
  })

  return {
    paint,
    destroy() {
      observer.disconnect()
      themeObserver.disconnect()
      resolution?.removeEventListener("change", watchResolution)
    },
  }
}

import type { IpodArtist, IpodCatalog, IpodLibrary, IpodSong } from "./types"

const collator = new Intl.Collator("en", {
  sensitivity: "base",
  ignorePunctuation: true,
  numeric: true,
})

const byName = (a: { name: string }, b: { name: string }) =>
  collator.compare(a.name, b.name)

export function createCatalog(library: IpodLibrary): IpodCatalog {
  const songs = [...library.songs].sort(byName)
  const songsById = new Map(songs.map((song) => [song.id, song]))

  const artistsByName = new Map<string, IpodArtist>()
  for (const song of songs) {
    const artist = artistsByName.get(song.artistName)
    if (artist) {
      artist.songIds.push(song.id)
    } else {
      artistsByName.set(song.artistName, {
        id: `artist:${song.artistName}`,
        name: song.artistName,
        songIds: [song.id],
      })
    }
  }

  return {
    songs,
    artists: [...artistsByName.values()].sort(byName),
    playlists: library.playlists,
    songsById,
  }
}

export function songsFromIds(ids: string[], catalog: IpodCatalog) {
  return ids
    .map((id) => catalog.songsById.get(id))
    .filter((song): song is IpodSong => !!song)
}

const GAIN = 0.3
/** Clicks closer together than this merge, like the piezo could not keep up. */
const MIN_SPACING_SECONDS = 0.05
const MAX_BACKLOG_SECONDS = 0.15
const RESUME_LEAD_SECONDS = 0.08
const STALE_RESUME_MS = 200

/** A 2ms burst of decaying noise, close to the click wheel's piezo tick. */
function createClickBuffer(context: AudioContext) {
  const { sampleRate } = context
  const length = Math.round(sampleRate * 0.003)
  const buffer = context.createBuffer(1, length, sampleRate)
  const data = buffer.getChannelData(0)
  const decay = sampleRate * 0.0007
  // Seeded so every click sounds the same.
  let seed = 7
  for (let i = 0; i < length; i += 1) {
    seed = (seed * 16807) % 2147483647
    const noise = (seed / 2147483647) * 2 - 1
    data[i] = noise * 0.72 * Math.exp(-i / decay)
  }
  return buffer
}

const resuming = new WeakSet<AudioContext>()

/** Browsers start contexts suspended until a gesture; resume on each one. */
export function resumeAudioContext(context: AudioContext) {
  if (context.state === "running" || context.state === "closed") return
  if (resuming.has(context)) return
  resuming.add(context)
  const done = () => resuming.delete(context)
  context.resume().catch(done).finally(done)
  setTimeout(done, 1000)
}

export function createClickSound(context: AudioContext) {
  const output = context.createGain()
  output.gain.value = GAIN
  output.connect(context.destination)
  const buffer = createClickBuffer(context)
  let nextStart = 0
  let requestedWhileSuspended: number | null = null

  function play() {
    const { currentTime } = context
    if (nextStart - currentTime >= MAX_BACKLOG_SECONDS) return
    const startAt = Math.max(currentTime, nextStart)
    const source = context.createBufferSource()
    source.buffer = buffer
    source.connect(output)
    source.start(startAt)
    nextStart = startAt + MIN_SPACING_SECONDS
  }

  function onStateChange() {
    if (context.state !== "running") return
    nextStart = Math.max(nextStart, context.currentTime + RESUME_LEAD_SECONDS)
    if (requestedWhileSuspended === null) return
    const isStale = Date.now() - requestedWhileSuspended > STALE_RESUME_MS
    requestedWhileSuspended = null
    if (!isStale) play()
  }

  context.addEventListener("statechange", onStateChange)

  return {
    playClick() {
      if (context.state !== "running") {
        resumeAudioContext(context)
        requestedWhileSuspended ??= Date.now()
        return
      }
      play()
    },
    destroy() {
      context.removeEventListener("statechange", onStateChange)
      output.disconnect()
    },
  }
}

import {
  isInertAtom,
  playbackAtom,
  scrollTargetAtom,
  seekAtom,
  settingsAtom,
  statusAtom,
  type IpodStore,
} from "./atoms"
import { createClickSound, resumeAudioContext } from "./click-sound"
import { BOOT_MIN_MS, DRAG_STEP_DEGREES, VOLUME_SAVE_MS } from "./constants"
import { createMenuController } from "./menu-controller"
import { createPlayback } from "./playback"
import { createTimeout } from "./timers"
import type { IpodSettings, RepeatMode, ScrollTarget } from "./types"
import type { WheelScroll } from "./wheel-gesture"
import { createHoldSeeker, createWheelScroller } from "./wheel-scroll"

const REPEAT_MODES: Record<IpodSettings["repeat"], RepeatMode> = {
  off: "none",
  one: "one",
  all: "all",
}

export type IpodEngine = ReturnType<typeof createIpodEngine>

/** Everything that needs the browser: audio, timers, and input handling. */
export function createIpodEngine({
  store,
  getMenuElement,
  getListElement,
}: {
  store: IpodStore
  getMenuElement: () => HTMLElement | null
  getListElement: () => HTMLElement | null
}) {
  const context = new AudioContext()
  const clickSound = createClickSound(context)
  const playback = createPlayback(store, context)
  const menu = createMenuController({
    store,
    playback,
    getMenuElement,
    getListElement,
  })
  const isInert = () => store.get(isInertAtom)
  const isSeeking = () => store.get(seekAtom).isSeeking
  const settings = () => store.get(settingsAtom)

  // Boot shows the logo for a moment, but only once the iPod is online.
  let hasBooted = false
  const setStatus = (partial: Partial<typeof statusAtom.init>) =>
    store.set(statusAtom, (status) => ({ ...status, ...partial }))
  const bootTimer = createTimeout(BOOT_MIN_MS, () =>
    setStatus({ isBooting: false })
  )

  function handleOnlineChange() {
    const isOnline = navigator.onLine
    setStatus({ isOnline })
    if (!isOnline) playback.pause()
    if (hasBooted) return
    if (isOnline) bootTimer.start()
    else bootTimer.stop()
  }

  handleOnlineChange()
  window.addEventListener("online", handleOnlineChange)
  window.addEventListener("offline", handleOnlineChange)

  // Volume is saved a moment after it settles, not on every step.
  const volumePercent = () => Math.round(store.get(playbackAtom).volume * 100)
  const volumeSaver = createTimeout(VOLUME_SAVE_MS, () =>
    store.set(settingsAtom, (value) => ({ ...value, volume: volumePercent() }))
  )
  let lastVolume = store.get(playbackAtom).volume

  let lastSettings: IpodSettings | undefined
  function applySettings() {
    const { shuffle, repeat } = settings()
    if (shuffle !== lastSettings?.shuffle) {
      playback.setShuffle(shuffle === "songs")
    }
    if (repeat !== lastSettings?.repeat) {
      playback.setRepeatMode(REPEAT_MODES[repeat])
    }
    lastSettings = settings()
  }

  const holdSeeker = createHoldSeeker()

  // Subscribing mounts settingsAtom, which loads the saved settings.
  const unsubscribers = [
    store.sub(settingsAtom, applySettings),
    store.sub(isInertAtom, () => {
      if (!isInert()) hasBooted = true
    }),
    store.sub(playbackAtom, () => {
      const { volume } = store.get(playbackAtom)
      if (volume === lastVolume) return
      lastVolume = volume
      if (volumePercent() !== settings().volume) volumeSaver.start()
    }),
    store.sub(seekAtom, () => {
      if (isSeeking()) holdSeeker.cancel()
    }),
  ]
  applySettings()
  playback.setVolume(settings().volume / 100)

  function handleUserActivity() {
    resumeAudioContext(context)
    menu.notifyActivity()
  }

  function click(count: number, target: ScrollTarget) {
    if (settings().clicker !== "on" || target === "seek") return
    for (let i = 0; i < count; i += 1) clickSound.playClick()
  }

  const scroller = createWheelScroller({ move: menu.move, click })

  function holdSeek(direction: number, isRepeat: boolean) {
    const state = store.get(playbackAtom)
    const time = holdSeeker.step(direction, isRepeat, {
      ...state,
      isInert: isInert(),
      isSeeking: isSeeking(),
    })
    if (time === undefined) return
    menu.notifyActivity()
    playback.seek(time)
  }

  /** Buttons do nothing until the iPod has booted and while offline. */
  const whenReady =
    <T extends unknown[]>(action: (...args: T) => void) =>
    (...args: T) => {
      if (!isInert()) action(...args)
    }

  const scrollTarget = () => store.get(scrollTargetAtom)

  return {
    menu,
    handleUserActivity,
    handleKeyActivity(event: KeyboardEvent) {
      if (!event.repeat || event.key.startsWith("Arrow")) handleUserActivity()
    },
    wheel: {
      scroll({ step, degrees, speed }: WheelScroll) {
        menu.notifyActivity()
        if (isInert()) return
        const target = scrollTarget()
        if (target === "brick") {
          menu.turnPaddle(step * degrees)
          return
        }
        scroller.scroll({
          step,
          degrees,
          target,
          multiplier: menu.accelerate(speed, step),
          dragStepDegrees: DRAG_STEP_DEGREES,
        })
      },
      keyScroll(step: number, heldMs: number) {
        menu.notifyActivity()
        if (isInert()) return
        if (menu.keyStep(step, heldMs)) click(1, scrollTarget())
      },
      dragStart() {
        scroller.reset()
        if (!store.get(statusAtom).isBooting) menu.seek.handleDragStart()
      },
      dragEnd: () => menu.seek.handleDragEnd(),
      steer: (direction: number | null) => menu.steerPaddle(direction ?? 0),
      select: whenReady(menu.select),
      selectHold: whenReady(menu.selectHold),
      menu: whenReady(menu.back),
      playPause: whenReady(menu.playPause),
      back: whenReady(() => {
        if (!isSeeking()) playback.skipPrevious()
      }),
      forward: whenReady(() => {
        if (!isSeeking()) playback.skipNext()
      }),
      backHold: (repeat: boolean) => holdSeek(-1, repeat),
      forwardHold: (repeat: boolean) => holdSeek(1, repeat),
    },
    /** The hidden sliders on Now Playing, for keyboard and screen readers. */
    sliders: {
      focusScrub() {
        if (!store.get(playbackAtom).hasLoadedItem) return
        menu.volume.exit()
        menu.seek.keepOpen()
      },
      scrub(time: number) {
        if (store.get(playbackAtom).hasLoadedItem) {
          menu.volume.exit()
          menu.seek.keepOpen()
        }
        menu.seek.seekTo(time)
      },
      commitScrub: menu.seek.commit,
      blurScrub: menu.seek.release,
      focusVolume() {
        menu.seek.exit()
        menu.volume.keepOpen()
      },
      setVolume(value: number) {
        menu.volume.keepOpen()
        menu.volume.set(value)
      },
      blurVolume: menu.volume.release,
    },
    destroy() {
      bootTimer.stop()
      volumeSaver.flush()
      window.removeEventListener("online", handleOnlineChange)
      window.removeEventListener("offline", handleOnlineChange)
      unsubscribers.forEach((unsubscribe) => unsubscribe())
      menu.destroy()
      playback.destroy()
      clickSound.destroy()
      context.close().catch(() => {})
    },
  }
}

import { RESET } from "jotai/utils"

import { createAccelerator, tierFor } from "./acceleration"
import {
  catalogAtom,
  DEFAULT_SETTINGS,
  isAdjustingVolumeAtom,
  itemsAtom,
  menuContextAtom,
  navigationAtom,
  playbackAtom,
  screenAtom,
  scrollTargetAtom,
  settingsAtom,
  viewAtom,
  type IpodStore,
  type NavigationState,
  type PlaybackState,
  type StackEntry,
} from "./atoms"
import {
  IDLE_JUMP_MS,
  LIST_ACCELERATION,
  SEEK_ACCELERATION,
  VOLUME_KEY_STEP,
} from "./constants"
import {
  getScreen,
  nowPlayingIndexIn,
  playItems,
  screenId,
  screenItems,
  songsForTarget,
  type MenuItem,
  type Screen,
} from "./menu"
import {
  createSeekController,
  createVolumeController,
} from "./now-playing-modes"
import type { Playback } from "./playback"
import { createTimeout } from "./timers"

export type BrickHandle = {
  launchBall: () => void
  movePaddle: (fraction: number) => void
  steerPaddle: (direction: number) => void
}

const NOW_PLAYING: Screen = { key: "now-playing" }

/** Remembers each list's last row, and which list started the queue. */
function createSelectionMemory() {
  const remembered = new Map<string, { itemId: string; index: number }>()
  let queueSource: string | undefined
  let lastQueue: PlaybackState["queue"] | undefined
  let lastIndex: number | undefined

  return {
    /** While the source list is closed, its row follows the playing song. */
    syncQueue({ queue, currentTrackIndex }: PlaybackState, stack: Screen[]) {
      if (queue === lastQueue && currentTrackIndex === lastIndex) return false
      lastQueue = queue
      lastIndex = currentTrackIndex
      const song = queue[currentTrackIndex]
      if (
        queueSource &&
        song &&
        !stack.some((entry) => screenId(entry) === queueSource)
      ) {
        remembered.set(queueSource, {
          itemId: song.id,
          index: currentTrackIndex,
        })
      }
      return true
    },
    remember(screen: Screen, items: MenuItem[], index: number) {
      const item = items[index]
      if (!item || getScreen(screen.key).forgetsSelection) return
      remembered.set(screenId(screen), { itemId: item.id, index })
    },
    indexIn(screen: Screen, items: MenuItem[]) {
      const entry = remembered.get(screenId(screen))
      if (!entry) return -1
      return items[entry.index]?.id === entry.itemId
        ? entry.index
        : items.findIndex((item) => item.id === entry.itemId)
    },
    setQueueSource(screen: Screen) {
      queueSource = screenId(screen)
    },
    clearQueueSource() {
      if (!queueSource) return
      remembered.delete(queueSource)
      queueSource = undefined
    },
  }
}

export function createMenuController({
  store,
  playback,
  getMenuElement,
  getListElement,
}: {
  store: IpodStore
  playback: Playback
  getMenuElement: () => HTMLElement | null
  getListElement: () => HTMLElement | null
}) {
  const seek = createSeekController(store, playback)
  const volume = createVolumeController(store, playback)
  const memory = createSelectionMemory()
  const listAccelerator = createAccelerator(LIST_ACCELERATION)
  let brick: BrickHandle | null = null
  /** The user moved the row, so it stops following the playing song. */
  let suppressSync = false

  const navigation = () => store.get(navigationAtom)
  const patch = (partial: Partial<NavigationState>) =>
    store.set(navigationAtom, (state) => ({ ...state, ...partial }))
  const top = () => store.get(screenAtom)
  const currentItems = () => store.get(itemsAtom)
  const itemsFor = (screen: Screen) =>
    screenItems(screen, store.get(menuContextAtom))

  function nowPlayingIndex(items: MenuItem[]) {
    const { queue, currentTrackIndex } = store.get(playbackAtom)
    return nowPlayingIndexIn(items, queue, currentTrackIndex)
  }

  function isFocusElsewhere() {
    const active = document.activeElement
    return (
      !!active &&
      active !== document.body &&
      !getMenuElement()?.contains(active)
    )
  }

  function initialIndexFor(screen: Screen) {
    const items = itemsFor(screen)
    const playing = nowPlayingIndex(items)
    return playing >= 0 ? playing : Math.max(0, memory.indexIn(screen, items))
  }

  function handleScreenChange(screen: Screen) {
    const isNowPlaying = getScreen(screen.key).view === "now-playing"
    seek.handleScreenChange(isNowPlaying)
    volume.handleScreenChange(isNowPlaying)
    listAccelerator.reset()
  }

  function push(screen: Screen, isIdleJump = false) {
    const { stack, selectedIndex, navigationId } = navigation()
    const current = top()
    const items = currentItems()
    memory.remember(current, items, selectedIndex)
    const annotated: StackEntry = {
      ...current,
      selectedItemId: items[selectedIndex]?.id,
      selectedIndexAtPush: selectedIndex,
      scrollTopAtPush: getListElement()?.scrollTop,
      suppressSyncAtPush: isIdleJump && suppressSync,
    }
    store.set(navigationAtom, {
      stack: [...stack.slice(0, -1), annotated, screen],
      selectedIndex: initialIndexFor(screen),
      navigationId: navigationId + 1,
      back: false,
      shouldFocus: isIdleJump
        ? !!getMenuElement()?.contains(document.activeElement)
        : !isFocusElsewhere(),
      restoredScrollTop: undefined,
    })
    suppressSync = false
    handleScreenChange(screen)
  }

  function pop() {
    const { stack, selectedIndex, navigationId } = navigation()
    if (stack.length <= 1) return
    memory.remember(top(), currentItems(), selectedIndex)
    const previous = stack.at(-2)!
    suppressSync = previous.suppressSyncAtPush ?? false

    const items = itemsFor(previous)
    const playing = nowPlayingIndex(items)
    const nextIndex =
      playing >= 0 && !suppressSync
        ? playing
        : Math.max(0, memory.indexIn(previous, items))

    store.set(navigationAtom, {
      stack: stack.slice(0, -1),
      selectedIndex: nextIndex,
      navigationId: navigationId + 1,
      back: true,
      shouldFocus: !isFocusElsewhere(),
      restoredScrollTop:
        nextIndex === previous.selectedIndexAtPush
          ? previous.scrollTopAtPush
          : undefined,
    })
    handleScreenChange(previous)
  }

  function moveBy(delta: number) {
    const items = currentItems()
    if (items.length === 0) return false
    const { selectedIndex } = navigation()
    const next = Math.min(items.length - 1, Math.max(0, selectedIndex + delta))
    if (next === selectedIndex) return false
    patch({ selectedIndex: next })
    suppressSync = true
    return true
  }

  function move(direction: number, count = 1) {
    switch (store.get(scrollTargetAtom)) {
      case "seek":
        return seek.seekBy(direction * count)
      case "volume":
        return volume.change(direction * count)
      case "list":
        return moveBy(direction * count)
      default:
        return false
    }
  }

  function accelerate(speed: number, direction: number) {
    const target = store.get(scrollTargetAtom)
    const seekMultiplier = seek.accelerate(speed, direction)
    const listMultiplier = listAccelerator.next(
      speed,
      direction,
      target === "list"
    )
    return target === "seek" ? seekMultiplier : listMultiplier
  }

  /** A held arrow key climbs the same tiers as a fast spin. */
  function keyStep(direction: number, heldMs: number) {
    switch (store.get(scrollTargetAtom)) {
      case "seek":
        return move(direction, tierFor(SEEK_ACCELERATION, heldMs))
      case "volume":
        return move(direction, VOLUME_KEY_STEP)
      default:
        return move(direction, tierFor(LIST_ACCELERATION, heldMs))
    }
  }

  function playFromItem(item: MenuItem | undefined) {
    if (item?.action !== "navigate") return false
    const songs = songsForTarget(
      item.target,
      item.contextId,
      store.get(catalogAtom)
    )
    if (songs.length === 0) return false
    memory.setQueueSource({ key: item.target, contextId: item.contextId })
    playback.play(songs)
    push(NOW_PLAYING)
    return true
  }

  function playItem(item: Extract<MenuItem, { action: "play" }>) {
    const items = currentItems()
    const { selectedIndex } = navigation()
    if (nowPlayingIndex(items) === selectedIndex) {
      if (!store.get(playbackAtom).isPlaying) playback.resume()
    } else {
      const { songsById } = store.get(catalogAtom)
      const plays = playItems(items)
      memory.setQueueSource(top())
      playback.play(
        plays
          .map((play) => songsById.get(play.songId))
          .filter((song) => song !== undefined),
        plays.indexOf(item)
      )
    }
    push(NOW_PLAYING)
  }

  function select() {
    const view = store.get(viewAtom)
    if (view === "brick") {
      brick?.launchBall()
      return
    }
    if (view === "now-playing") {
      if (store.get(isAdjustingVolumeAtom)) {
        volume.exit()
      } else if (store.get(playbackAtom).hasLoadedItem) {
        seek.toggle()
      }
      return
    }

    const item = currentItems()[navigation().selectedIndex]
    switch (item?.action) {
      case "navigate":
        push({
          key: item.target,
          contextId: item.contextId,
          title: item.screenTitle,
        })
        break
      case "inline-toggle":
        store.set(settingsAtom, (settings) => {
          const { values, toggleKey } = item
          const index = values.indexOf(settings[toggleKey])
          return {
            ...settings,
            [toggleKey]: values[(index + 1) % values.length],
          }
        })
        break
      case "cancel":
        pop()
        break
      case "reset-all":
        store.set(settingsAtom, RESET)
        playback.setVolume(DEFAULT_SETTINGS.volume / 100)
        pop()
        break
      case "play":
        playItem(item)
        break
    }
  }

  function playPause() {
    const state = store.get(playbackAtom)
    if (state.hasLoadedItem) {
      if (state.isPlaying) playback.pause()
      else playback.resume()
      return
    }
    if (state.isLoading) {
      playback.pause()
      return
    }
    const item = currentItems()[navigation().selectedIndex]
    if (playFromItem(item)) return
    if (item?.action === "play") playItem(item)
    else if (state.queue.length > 0) playback.resume()
  }

  function selectHold() {
    const hold = getScreen(top().key).selectHold
    if (hold) push({ key: hold.target })
  }

  const idleJump = createTimeout(IDLE_JUMP_MS, () => push(NOW_PLAYING, true))
  let isIdleJumpArmed = false

  function syncIdleJump() {
    const armed =
      store.get(playbackAtom).isPlaying && !getScreen(top().key).blocksIdleJump
    if (armed === isIdleJumpArmed) return
    isIdleJumpArmed = armed
    if (armed) idleJump.start()
    else idleJump.stop()
  }

  /** Keeps the row on the playing song and inside the list. */
  function sync() {
    const items = currentItems()
    const { selectedIndex, stack } = navigation()
    if (selectedIndex >= items.length) {
      patch({ selectedIndex: Math.max(0, items.length - 1) })
    }
    if (memory.syncQueue(store.get(playbackAtom), stack)) {
      const playing = nowPlayingIndex(items)
      if (playing >= 0 && !suppressSync) patch({ selectedIndex: playing })
    }
    syncIdleJump()
  }

  const unsubscribers = [
    store.sub(playbackAtom, sync),
    store.sub(itemsAtom, sync),
    store.sub(screenAtom, syncIdleJump),
    playback.onQueueFinished(() => {
      memory.clearQueueSource()
      if (store.get(viewAtom) !== "now-playing") return
      pop()
      // The Now Playing row it came from no longer exists.
      if (top().selectedItemId === NOW_PLAYING.key) {
        patch({ selectedIndex: 0, restoredScrollTop: undefined })
      }
    }),
  ]

  return {
    seek,
    volume,
    back: pop,
    select,
    selectHold,
    playPause,
    accelerate,
    move,
    keyStep,
    /** Any input restarts the countdown to Now Playing. */
    notifyActivity() {
      if (isIdleJumpArmed) idleJump.start()
    },
    registerBrick(handle: BrickHandle | null) {
      brick = handle
    },
    turnPaddle(degrees: number) {
      brick?.movePaddle(degrees / 360)
    },
    steerPaddle(direction: number) {
      brick?.steerPaddle(direction)
    },
    destroy() {
      unsubscribers.forEach((unsubscribe) => unsubscribe())
      idleJump.stop()
      seek.destroy()
      volume.destroy()
    },
  }
}

import { songsFromIds } from "./catalog"
import { SELECT_HOLD_BRICK_MS } from "./constants"
import type { IpodCatalog, IpodSettings, IpodSong } from "./types"

export type ScreenKey =
  | "main"
  | "settings"
  | "about"
  | "reset-settings"
  | "playlists"
  | "artists"
  | "songs"
  | "playlist-tracks"
  | "artist-tracks"
  | "now-playing"
  | "brick"

export type ToggleKey = "shuffle" | "repeat" | "clicker"

export type MenuItem = { id: string; title: string } & (
  | {
      action: "navigate"
      target: ScreenKey
      contextId?: string
      screenTitle?: string
    }
  | { action: "inline-toggle"; toggleKey: ToggleKey; values: string[] }
  | { action: "cancel" }
  | { action: "reset-all" }
  | { action: "play"; songId: string }
  | { action: "info"; value?: string; centered?: boolean }
)

export type Screen = {
  key: ScreenKey
  contextId?: string
  /** Overrides the screen's own title, e.g. Artists > All shows "All Songs". */
  title?: string
}

/** What every list is built from, apart from the screen itself. */
export type MenuContext = {
  catalog: IpodCatalog
  hasNowPlaying: boolean
}

type ItemsContext = MenuContext & { contextId?: string }

type ScreenDefinition = {
  view: "list" | "now-playing" | "brick"
  title: string | ((catalog: IpodCatalog, contextId?: string) => string)
  items?: (context: ItemsContext) => MenuItem[]
  /** Main menu gains a Now Playing row while something is queued. */
  listsNowPlaying?: boolean
  /** Holding Select this long opens `target`. */
  selectHold?: { ms: number; target: ScreenKey }
  /** Reopening starts from the top instead of the last row. */
  forgetsSelection?: boolean
  /** Playing music does not jump here to Now Playing when idle. */
  blocksIdleJump?: boolean
}

const VALUE_LABELS: Record<string, string> = {
  off: "Off",
  on: "On",
  songs: "Songs",
  one: "One",
  all: "All",
}

function settingValueLabel(value: string) {
  return VALUE_LABELS[value] ?? value
}

const TOGGLE_VALUES: Record<ToggleKey, string[]> = {
  shuffle: ["off", "songs"],
  repeat: ["off", "one", "all"],
  clicker: ["off", "on"],
}

const TOGGLE_TITLES: Record<ToggleKey, string> = {
  shuffle: "Shuffle",
  repeat: "Repeat",
  clicker: "Clicker",
}

const NO_MUSIC: MenuItem[] = [
  { id: "no-music", title: "No Music", action: "info", centered: true },
]

const orNoMusic = (items: MenuItem[]) => (items.length ? items : NO_MUSIC)

function navigate(key: ScreenKey): MenuItem {
  const { title } = SCREENS[key]
  return {
    id: key,
    title: typeof title === "string" ? title : key,
    action: "navigate",
    target: key,
  }
}

function inlineToggle(key: ToggleKey): MenuItem {
  return {
    id: key,
    title: TOGGLE_TITLES[key],
    action: "inline-toggle",
    toggleKey: key,
    values: TOGGLE_VALUES[key],
  }
}

const gigabytes = new Intl.NumberFormat("en-US", {
  style: "unit",
  unit: "gigabyte",
  maximumFractionDigits: 1,
})
const integer = new Intl.NumberFormat("en-US")

// The original 5 GB iPod (2001), after formatting.
const CAPACITY_GB = 4.6
// Apple's "1,000 songs" math: four minutes at 160 kbps.
const SONG_SIZE_GB = 0.0048

export function songsForTarget(
  target: ScreenKey,
  contextId: string | undefined,
  catalog: IpodCatalog
): IpodSong[] {
  switch (target) {
    case "songs":
      return catalog.songs
    case "playlist-tracks":
      return songsFromIds(
        catalog.playlists.find((playlist) => playlist.id === contextId)
          ?.songIds ?? [],
        catalog
      )
    case "artist-tracks":
      return songsFromIds(
        catalog.artists.find((artist) => artist.id === contextId)?.songIds ??
          [],
        catalog
      )
    default:
      return []
  }
}

function trackItems(target: ScreenKey) {
  return ({ catalog, contextId }: ItemsContext) =>
    orNoMusic(
      songsForTarget(target, contextId, catalog).map((song) => ({
        id: song.id,
        title: song.name,
        action: "play",
        songId: song.id,
      }))
    )
}

const SCREENS: Record<ScreenKey, ScreenDefinition> = {
  main: {
    view: "list",
    title: "iPod",
    listsNowPlaying: true,
    items: ({ hasNowPlaying }) => [
      navigate("playlists"),
      navigate("artists"),
      navigate("songs"),
      navigate("settings"),
      ...(hasNowPlaying ? [navigate("now-playing")] : []),
    ],
  },
  settings: {
    view: "list",
    title: "Settings",
    items: () => [
      navigate("about"),
      inlineToggle("shuffle"),
      inlineToggle("repeat"),
      inlineToggle("clicker"),
      navigate("reset-settings"),
    ],
  },
  about: {
    view: "list",
    title: "About",
    selectHold: { ms: SELECT_HOLD_BRICK_MS, target: "brick" },
    items: ({ catalog }) => [
      // The name an iPod is given in iTunes; a new one is just "iPod".
      { id: "name", title: "ncdai iPod", action: "info", centered: true },
      {
        id: "songs-count",
        title: "Songs",
        action: "info",
        value: integer.format(catalog.songs.length),
      },
      {
        id: "capacity",
        title: "Capacity",
        action: "info",
        value: gigabytes.format(CAPACITY_GB),
      },
      {
        id: "available",
        title: "Available",
        action: "info",
        value: gigabytes.format(
          Math.max(0, CAPACITY_GB - catalog.songs.length * SONG_SIZE_GB)
        ),
      },
      { id: "version", title: "Version", action: "info", value: "1.0" },
    ],
  },
  "reset-settings": {
    view: "list",
    title: "Reset All Settings",
    forgetsSelection: true,
    items: () => [
      { id: "cancel", title: "Cancel", action: "cancel" },
      { id: "reset-all", title: "Reset", action: "reset-all" },
    ],
  },
  playlists: {
    view: "list",
    title: "Playlists",
    items: ({ catalog }) =>
      orNoMusic(
        catalog.playlists.map((playlist) => ({
          id: playlist.id,
          title: playlist.name,
          action: "navigate",
          target: "playlist-tracks",
          contextId: playlist.id,
        }))
      ),
  },
  artists: {
    view: "list",
    title: "Artists",
    items: ({ catalog }) => {
      const items: MenuItem[] = catalog.artists.map((artist) => ({
        id: artist.id,
        title: artist.name,
        action: "navigate",
        target: "artist-tracks",
        contextId: artist.id,
      }))
      if (items.length && catalog.songs.length) {
        items.unshift({
          id: "all",
          title: "All",
          action: "navigate",
          target: "songs",
          screenTitle: "All Songs",
        })
      }
      return orNoMusic(items)
    },
  },
  songs: {
    view: "list",
    title: "Songs",
    items: trackItems("songs"),
  },
  "playlist-tracks": {
    view: "list",
    title: (catalog, contextId) =>
      catalog.playlists.find((playlist) => playlist.id === contextId)?.name ??
      "Playlists",
    items: trackItems("playlist-tracks"),
  },
  "artist-tracks": {
    view: "list",
    title: (catalog, contextId) =>
      catalog.artists.find((artist) => artist.id === contextId)?.name ??
      "Artists",
    items: trackItems("artist-tracks"),
  },
  "now-playing": {
    view: "now-playing",
    title: "Now Playing",
    blocksIdleJump: true,
  },
  brick: {
    view: "brick",
    title: "Brick",
    blocksIdleJump: true,
  },
}

export function getScreen(key: ScreenKey) {
  return SCREENS[key]
}

export function screenTitle(screen: Screen, catalog: IpodCatalog) {
  if (screen.title) return screen.title
  const { title } = SCREENS[screen.key]
  return typeof title === "string" ? title : title(catalog, screen.contextId)
}

export function screenItems(screen: Screen, context: MenuContext) {
  const definition = SCREENS[screen.key]
  return (
    definition.items?.({
      ...context,
      contextId: screen.contextId,
      hasNowPlaying: context.hasNowPlaying && !!definition.listsNowPlaying,
    }) ?? []
  )
}

export function screenId({ key, contextId }: Screen) {
  return `${key}:${contextId ?? ""}`
}

export function playItems(items: MenuItem[]) {
  return items.filter(
    (item): item is Extract<MenuItem, { action: "play" }> =>
      item.action === "play"
  )
}

/**
 * Where the playing song sits in `items`, but only when the list is exactly
 * the queue, so a list follows playback only if it started it.
 */
export function nowPlayingIndexIn(
  items: MenuItem[],
  queue: IpodSong[],
  currentTrackIndex: number
) {
  const plays = playItems(items)
  const matches =
    plays.length > 0 &&
    plays.length === queue.length &&
    plays.every((item, index) => item.songId === queue[index]?.id)
  return matches ? items.indexOf(plays[currentTrackIndex]) : -1
}

export function settingValue(item: MenuItem, settings: IpodSettings) {
  if (item.action === "inline-toggle") {
    return settingValueLabel(settings[item.toggleKey])
  }
  if (item.action === "info") return item.value
}

import { createAccelerator } from "./acceleration"
import {
  isAdjustingVolumeAtom,
  playbackAtom,
  seekAtom,
  type IpodStore,
  type PlaybackState,
} from "./atoms"
import {
  SEEK_ACCELERATION,
  SEEK_COMMIT_MS,
  SEEK_IDLE_MS,
  VOLUME_IDLE_MS,
} from "./constants"
import type { Playback } from "./playback"
import { createTimeout } from "./timers"

/** A mode that closes itself after a quiet spell, unless held open. */
function createIdleMode(options: {
  timeoutMs: number
  isActive: () => boolean
  enter: () => void
  onLeave: () => void
}) {
  let keptOpen = false
  const timer = createTimeout(options.timeoutMs, leave)

  function leave() {
    if (!options.isActive()) return
    timer.stop()
    options.onLeave()
  }

  function exit() {
    keptOpen = false
    leave()
  }

  return {
    restartIdleTimer() {
      if (!keptOpen) timer.start()
    },
    /** Focus on a slider holds the mode open. */
    keepOpen() {
      keptOpen = true
      timer.stop()
      if (!options.isActive()) options.enter()
    },
    release() {
      keptOpen = false
      if (options.isActive()) timer.start()
    },
    exit,
    reenter() {
      const wasKeptOpen = keptOpen
      leave()
      if (wasKeptOpen) options.enter()
    },
    /** Leaving Now Playing closes the mode. */
    handleScreenChange(isNowPlaying: boolean) {
      if (!isNowPlaying) exit()
    },
    destroy: timer.stop,
  }
}

/** Select on Now Playing: the wheel scrubs through the song. */
export function createSeekController(store: IpodStore, playback: Playback) {
  const accelerator = createAccelerator(SEEK_ACCELERATION)
  const playbackState = () => store.get(playbackAtom)
  const isSeeking = () => store.get(seekAtom).isSeeking
  const setPreview = (previewTime: number | undefined) =>
    store.set(seekAtom, (state) => ({ ...state, previewTime }))
  let pending: number | undefined
  let generation = 0
  let isDragging = false
  let enteredTrack: number | undefined
  let enteredQueue: PlaybackState["queue"] | undefined
  const commitTimer = createTimeout(SEEK_COMMIT_MS, commit)

  function commit() {
    commitTimer.stop()
    if (pending === undefined) return
    const time = pending
    pending = undefined
    const current = ++generation
    playback.seek(time).then(() => {
      if (current === generation) setPreview(undefined)
    })
  }

  function enter() {
    const { currentTrackIndex, queue } = playbackState()
    enteredTrack = currentTrackIndex
    enteredQueue = queue
    idle.restartIdleTimer()
    store.set(seekAtom, { isSeeking: true })
  }

  function leave() {
    commit()
    enteredTrack = undefined
    enteredQueue = undefined
    isDragging = false
    store.set(seekAtom, { isSeeking: false })
  }

  const idle = createIdleMode({
    timeoutMs: SEEK_IDLE_MS,
    isActive: isSeeking,
    enter,
    onLeave: leave,
  })

  function shownTime() {
    return (
      store.get(seekAtom).previewTime ?? Math.floor(playbackState().currentTime)
    )
  }

  function seekTo(time: number) {
    if (!isSeeking()) return false
    const { duration } = playbackState()
    const max = duration > 0 ? duration : Infinity
    const target = Math.min(max, Math.max(0, Math.round(time)))
    idle.restartIdleTimer()
    if (target === shownTime()) return false
    pending = target
    generation += 1
    if (!isDragging) commitTimer.start()
    setPreview(target)
    return true
  }

  const unsubscribe = store.sub(playbackAtom, () => {
    if (!isSeeking()) return
    const { currentTrackIndex, queue, duration, hasLoadedItem } =
      playbackState()
    if (currentTrackIndex !== enteredTrack || queue !== enteredQueue) {
      if (hasLoadedItem) idle.reenter()
      else idle.exit()
      return
    }
    const { previewTime } = store.get(seekAtom)
    if (duration > 0 && previewTime !== undefined && previewTime > duration) {
      if (pending !== undefined) pending = duration
      setPreview(duration)
    }
  })

  return {
    toggle() {
      if (isSeeking()) idle.exit()
      else enter()
    },
    seekTo,
    seekBy: (seconds: number) => seekTo(shownTime() + seconds),
    commit,
    accelerate(speed: number, direction: number) {
      if (isSeeking()) idle.restartIdleTimer()
      return accelerator.next(speed, direction, isSeeking())
    },
    keepOpen: idle.keepOpen,
    release() {
      commit()
      idle.release()
    },
    exit: idle.exit,
    handleScreenChange: idle.handleScreenChange,
    /** The commit waits for the finger to lift, so audio does not stutter. */
    handleDragStart() {
      isDragging = true
      commitTimer.stop()
    },
    handleDragEnd() {
      isDragging = false
      if (pending !== undefined) commitTimer.start()
    },
    destroy() {
      commit()
      idle.destroy()
      unsubscribe()
    },
  }
}

/** Turning the wheel on Now Playing changes the volume. */
export function createVolumeController(store: IpodStore, playback: Playback) {
  const isAdjusting = () => store.get(isAdjustingVolumeAtom)
  const setAdjusting = (value: boolean) =>
    store.set(isAdjustingVolumeAtom, value)
  const percent = () => Math.round(store.get(playbackAtom).volume * 100)

  const idle = createIdleMode({
    timeoutMs: VOLUME_IDLE_MS,
    isActive: isAdjusting,
    enter: () => setAdjusting(true),
    onLeave: () => setAdjusting(false),
  })

  function set(value: number) {
    const next = Math.min(100, Math.max(0, value))
    idle.restartIdleTimer()
    setAdjusting(true)
    if (next === percent()) return false
    playback.setVolume(next / 100)
    return true
  }

  return {
    set,
    change: (delta: number) => set(percent() + delta),
    keepOpen: idle.keepOpen,
    release: idle.release,
    exit: idle.exit,
    handleScreenChange: idle.handleScreenChange,
    destroy: idle.destroy,
  }
}

import { playbackAtom, type IpodStore, type PlaybackState } from "./atoms"
import { CrossfadePlayer } from "./player"
import type { IpodSong, RepeatMode } from "./types"

export type Playback = ReturnType<typeof createPlayback>

/** Owns the queue and one CrossfadePlayer for it, mirrored into `playbackAtom`. */
export function createPlayback(store: IpodStore, context: AudioContext) {
  let player: CrossfadePlayer | undefined
  let startAbort: AbortController | undefined
  let shuffle = false
  let repeatMode: RepeatMode = "none"
  const queueFinishedListeners = new Set<() => void>()

  const get = () => store.get(playbackAtom)
  const patch = (partial: Partial<PlaybackState>) =>
    store.set(playbackAtom, (state) => ({ ...state, ...partial }))

  // Controls run one after another so a skip never races a pending start.
  let chain = Promise.resolve()
  function enqueue(task: () => Promise<void> | void) {
    chain = chain.then(async () => {
      try {
        await task()
      } catch {
        // A failed control (e.g. blocked autoplay) leaves the state as is.
      }
    })
    return chain
  }

  function destroyPlayer() {
    const previous = player
    player = undefined
    previous?.destroy()
  }

  function clearQueue() {
    startAbort?.abort()
    patch({
      queue: [],
      currentTrackIndex: 0,
      queuePosition: 0,
      hasLoadedItem: false,
      isPlaying: false,
      isLoading: false,
    })
    return enqueue(destroyPlayer)
  }

  function start(queue: IpodSong[], index: number) {
    startAbort?.abort()
    const abort = new AbortController()
    startAbort = abort
    patch({
      queue,
      currentTrackIndex: index,
      // Shuffle pins the chosen song first.
      queuePosition: shuffle ? 0 : index,
      isLoading: true,
    })

    return enqueue(async () => {
      if (abort.signal.aborted) return
      try {
        destroyPlayer()
        let hadItem = false
        const next: CrossfadePlayer = new CrossfadePlayer({
          urls: queue.map((song) => song.previewUrl),
          context,
          shuffle,
          repeatMode,
          onAdvance(trackIndex) {
            if (trackIndex < get().queue.length) {
              patch({ currentTrackIndex: trackIndex })
            }
          },
          onChange(state) {
            // A replaced player still reports while it tears down.
            if (player !== next) return
            patch(state)
            if (state.hasLoadedItem === undefined) return
            const didFinish = hadItem && !state.hasLoadedItem
            hadItem = state.hasLoadedItem
            if (didFinish && get().queue.length > 0) {
              clearQueue()
              queueFinishedListeners.forEach((listener) => listener())
            }
          },
        })
        player = next
        next.setVolume(get().volume)
        await next.jumpTo(index, true)
      } finally {
        if (!abort.signal.aborted) patch({ isLoading: false })
      }
    })
  }

  return {
    play(queue: IpodSong[], index?: number) {
      if (queue.length === 0) return Promise.resolve()
      const startIndex =
        index ?? (shuffle ? Math.floor(Math.random() * queue.length) : 0)
      return start(queue, startIndex)
    },
    pause: () => enqueue(() => player?.pause()),
    resume: () => enqueue(() => player?.resume()),
    skipNext: () => enqueue(() => player?.skipToNext()),
    skipPrevious: () => enqueue(() => player?.skipToPrevious()),
    seek(time: number) {
      const index = get().currentTrackIndex
      return enqueue(() => player?.seek(time, index))
    },
    setVolume(volume: number) {
      patch({ volume })
      player?.setVolume(volume)
    },
    setShuffle(enabled: boolean) {
      shuffle = enabled
      return enqueue(() => player?.setShuffle(enabled))
    },
    setRepeatMode(mode: RepeatMode) {
      repeatMode = mode
      return enqueue(() => player?.setRepeatMode(mode))
    },
    onQueueFinished(listener: () => void) {
      queueFinishedListeners.add(listener)
      return () => {
        queueFinishedListeners.delete(listener)
      }
    },
    destroy() {
      startAbort?.abort()
      destroyPlayer()
    },
  }
}

import { CROSSFADE_SECONDS, RESTART_THRESHOLD_SECONDS } from "./constants"
import type { RepeatMode } from "./types"

const CURVE_POINTS = 50

function curve(fn: (t: number) => number) {
  return Float32Array.from({ length: CURVE_POINTS }, (_, i) =>
    fn(i / (CURVE_POINTS - 1))
  )
}

// Equal-power curves keep the sum steady while two songs overlap.
const FADE_IN = curve((t) => Math.cos((1 - t) * Math.PI * 0.5))
const FADE_OUT = curve((t) => Math.cos(t * Math.PI * 0.5))

function shuffle<T>(items: T[]) {
  const result = [...items]
  for (let i = result.length - 1; i > 0; i -= 1) {
    const j = Math.floor(Math.random() * (i + 1))
    ;[result[i], result[j]] = [result[j], result[i]]
  }
  return result
}

/** One song's audio element, routed through its own fade gain. */
class Channel {
  readonly audio: HTMLAudioElement
  private readonly context: AudioContext
  private readonly gain: GainNode
  private readonly source: MediaElementAudioSourceNode
  private fadeDone: ReturnType<typeof setTimeout> | undefined

  constructor(context: AudioContext, url: string, output: AudioNode) {
    this.audio = new Audio()
    this.audio.preload = "auto"
    this.audio.crossOrigin = "anonymous"
    this.audio.src = url
    this.context = context
    this.gain = context.createGain()
    this.gain.gain.value = 0
    this.source = context.createMediaElementSource(this.audio)
    this.source.connect(this.gain).connect(output)
  }

  private cancelFade() {
    clearTimeout(this.fadeDone)
    this.gain.gain.cancelScheduledValues(this.context.currentTime)
  }

  private fade(values: Float32Array, onDone?: () => void) {
    this.cancelFade()
    this.gain.gain.setValueCurveAtTime(
      values,
      this.context.currentTime,
      CROSSFADE_SECONDS
    )
    if (onDone) this.fadeDone = setTimeout(onDone, CROSSFADE_SECONDS * 1000)
  }

  fadeIn() {
    this.fade(FADE_IN)
  }

  fadeOut(onDone?: () => void) {
    this.fade(FADE_OUT, onDone)
  }

  cutIn() {
    this.cancelFade()
    this.gain.gain.setValueAtTime(1, this.context.currentTime)
  }

  destroy() {
    clearTimeout(this.fadeDone)
    this.audio.pause()
    this.audio.removeAttribute("src")
    this.audio.load()
    this.source.disconnect()
    this.gain.disconnect()
  }
}

type PlayerState = {
  isPlaying: boolean
  currentTime: number
  duration: number
  hasLoadedItem: boolean
  /** Position in play order, which differs from the queue when shuffled. */
  queuePosition: number
}

/**
 * Plays a queue like a DJ with two turntables: the channel playing now and
 * the one cued up next, crossfaded over the last seconds of each song.
 */
export class CrossfadePlayer {
  private readonly state: PlayerState = {
    isPlaying: false,
    currentTime: 0,
    duration: 0,
    hasLoadedItem: false,
    queuePosition: 0,
  }

  private readonly urls: string[]
  private readonly context: AudioContext
  /** The song shown on screen changed to `index`. */
  private readonly onAdvance: (index: number) => void
  private readonly onChange: (state: Partial<PlayerState>) => void
  private readonly volumeGain: GainNode

  private currentIndex = 0
  private current: Channel | undefined
  private next: Channel | undefined
  private nextIndex: number | undefined
  /** The channel whose time is on screen; lags `current` mid-crossfade. */
  private display: Channel | undefined
  private readonly fading = new Set<Channel>()
  private pendingCrossfadeFrom: { channel: Channel; index: number } | undefined
  private hasTriggeredFade = false
  private isShuffled: boolean
  private repeatMode: RepeatMode
  private playOrder: number[] = []

  constructor(options: {
    urls: string[]
    context: AudioContext
    shuffle: boolean
    repeatMode: RepeatMode
    onAdvance: (index: number) => void
    onChange: (state: Partial<PlayerState>) => void
  }) {
    this.urls = options.urls
    this.context = options.context
    this.onAdvance = options.onAdvance
    this.onChange = options.onChange
    this.volumeGain = this.context.createGain()
    this.volumeGain.connect(this.context.destination)
    this.isShuffled = options.shuffle
    this.repeatMode = options.repeatMode
  }

  private patch(partial: Partial<PlayerState>) {
    Object.assign(this.state, partial)
    this.onChange(partial)
  }

  private setCurrent(channel: Channel | undefined) {
    this.current = channel
    this.patch({ hasLoadedItem: !!channel })
  }

  private clearNext() {
    this.next?.destroy()
    this.next = undefined
    this.nextIndex = undefined
  }

  private promoteNext() {
    this.setCurrent(this.next)
    this.next = undefined
    this.nextIndex = undefined
  }

  private destroyActive() {
    this.current?.destroy()
    this.clearNext()
    this.setCurrent(undefined)
    this.display = undefined
  }

  private destroyFading() {
    this.fading.forEach((channel) => channel.destroy())
    this.fading.clear()
  }

  private createChannel(index: number) {
    const url = this.urls[index]
    if (url === undefined) return
    const channel = new Channel(this.context, url, this.volumeGain)
    this.bind(channel)
    return channel
  }

  private setDuration(audio: HTMLAudioElement) {
    if (
      Number.isFinite(audio.duration) &&
      audio.duration !== this.state.duration
    ) {
      this.patch({ duration: audio.duration })
    }
  }

  /** Duration stays 0 until the channel knows its own. */
  private syncToChannel(channel: Channel | undefined) {
    this.patch({
      currentTime: channel?.audio.currentTime ?? 0,
      duration:
        channel && Number.isFinite(channel.audio.duration)
          ? channel.audio.duration
          : 0,
    })
  }

  private syncQueuePosition(index = this.currentIndex) {
    this.patch({
      queuePosition: this.isShuffled ? this.playOrder.indexOf(index) : index,
    })
  }

  private promoteToDisplay(channel: Channel) {
    if (channel === this.display) return
    this.display = channel
    this.syncToChannel(channel)
    this.onAdvance(this.currentIndex)
    this.syncQueuePosition()
    this.pendingCrossfadeFrom = undefined
  }

  // Channels are compared by reference: repeat-one crossfades a song into
  // a new instance of itself, so an index can match both.
  private bind(channel: Channel) {
    const { audio } = channel

    audio.addEventListener("durationchange", () => {
      if (channel === this.display) this.setDuration(audio)
    })

    audio.addEventListener("timeupdate", () => {
      if (
        channel === this.current &&
        audio.currentTime >= CROSSFADE_SECONDS / 2
      ) {
        this.promoteToDisplay(channel)
      }
      if (channel === this.display) {
        this.patch({ currentTime: audio.currentTime })
        this.setDuration(audio)
      }
      if (channel !== this.current) return

      const { currentTime, duration } = audio
      if (
        !Number.isFinite(duration) ||
        duration <= CROSSFADE_SECONDS ||
        this.hasTriggeredFade ||
        currentTime < duration - CROSSFADE_SECONDS
      ) {
        return
      }
      this.hasTriggeredFade = true
      if (this.next) this.crossfadeToNext()
      else channel.fadeOut()
    })

    audio.addEventListener("ended", () => {
      if (channel !== this.current) return
      this.promoteToDisplay(channel)
      if (this.next) {
        this.crossfadeToNext()
        return
      }
      this.endQueue()
    })
  }

  private endQueue() {
    this.destroyActive()
    this.destroyFading()
    this.pendingCrossfadeFrom = undefined
    this.patch({ isPlaying: false })
    this.syncToChannel(undefined)
  }

  private autoAdvanceIndex(from: number) {
    return this.repeatMode === "one" ? from : this.adjacentIndex(from, 1)
  }

  private displayedIndex() {
    return this.pendingCrossfadeFrom?.index ?? this.currentIndex
  }

  /** Manual skips always land on a different song. */
  private adjacentIndex(from: number, direction: 1 | -1) {
    const wraps = this.repeatMode === "all"

    if (!this.isShuffled) {
      const index = from + direction
      if (index >= 0 && index < this.urls.length) return index
      if (!wraps) return
      return direction === 1 ? 0 : this.urls.length - 1
    }

    const position = this.playOrder.indexOf(from) + direction
    if (position >= 0 && position < this.playOrder.length) {
      return this.playOrder[position]
    }
    if (!wraps) return
    return this.playOrder[direction === 1 ? 0 : this.playOrder.length - 1]
  }

  /** Re-cues the second turntable whenever the index, shuffle or repeat changes. */
  private prepareNext() {
    if (!this.current) return
    const index = this.autoAdvanceIndex(this.currentIndex)
    if (index === this.nextIndex) return
    this.clearNext()
    if (index === undefined) return
    this.nextIndex = index
    this.next = this.createChannel(index)
  }

  private crossfadeToNext() {
    const from = this.current
    const to = this.next
    if (!from || !to || this.nextIndex === undefined) return

    this.pendingCrossfadeFrom ??= { channel: from, index: this.currentIndex }
    from.fadeOut(() => {
      from.destroy()
      this.fading.delete(from)
      if (this.pendingCrossfadeFrom?.channel === from) {
        this.pendingCrossfadeFrom = undefined
        if (this.current) this.promoteToDisplay(this.current)
      } else if (to === this.current) {
        this.promoteToDisplay(to)
      }
    })
    this.fading.add(from)

    to.audio.play().catch(() => {
      if (to !== this.current) return
      this.patch({ isPlaying: false })
      this.promoteToDisplay(to)
    })
    to.fadeIn()

    this.currentIndex = this.nextIndex
    this.promoteNext()
    this.hasTriggeredFade = false
    this.prepareNext()
  }

  /** Undoes a crossfade that started but is not on screen yet. */
  private revertPendingCrossfade() {
    const pending = this.pendingCrossfadeFrom
    if (!pending) return
    this.pendingCrossfadeFrom = undefined
    this.current?.destroy()
    pending.channel.cutIn()
    this.fading.delete(pending.channel)
    this.destroyFading()
    this.currentIndex = pending.index
    this.setCurrent(pending.channel)
    this.clearNext()
    this.hasTriggeredFade = false
    this.syncQueuePosition()
    this.prepareNext()
  }

  private restartInPlace(channel: Channel) {
    channel.audio.currentTime = 0
    channel.cutIn()
    this.hasTriggeredFade = false
    this.pendingCrossfadeFrom = undefined
    this.syncToChannel(channel)
  }

  /** Repeat-one locks Next and Previous to the current song. */
  private restartIfRepeatOne() {
    if (this.repeatMode !== "one") return false
    if (this.current) this.restartInPlace(this.current)
    return true
  }

  async resume() {
    const channel = this.current
    if (!channel) {
      await this.jumpTo(this.currentIndex, true)
      return
    }
    await channel.audio.play()
    channel.cutIn()
    this.hasTriggeredFade = false
    this.patch({ isPlaying: true })
  }

  pause() {
    this.current?.audio.pause()
    this.fading.forEach((channel) => channel.audio.pause())
    this.patch({ isPlaying: false })
  }

  async skipToNext() {
    if (this.restartIfRepeatOne()) return
    const index = this.adjacentIndex(this.currentIndex, 1)
    if (index !== undefined) {
      await this.jumpTo(index)
      return
    }
    if (!this.pendingCrossfadeFrom && this.current) this.endQueue()
  }

  /** Restarts a song that has played a while, otherwise goes back one. */
  async skipToPrevious() {
    if (this.restartIfRepeatOne()) return
    const channel = this.current
    if (
      channel &&
      this.state.isPlaying &&
      channel.audio.currentTime > RESTART_THRESHOLD_SECONDS
    ) {
      this.restartInPlace(channel)
      return
    }
    const index = this.adjacentIndex(this.currentIndex, -1)
    if (index !== undefined) {
      await this.jumpTo(index)
      return
    }
    if (!this.pendingCrossfadeFrom && channel) this.endQueue()
  }

  async jumpTo(index: number, forceResume = false) {
    if (
      (index === this.currentIndex && this.current) ||
      index < 0 ||
      index >= this.urls.length
    ) {
      return
    }
    const shouldPlay = forceResume || this.state.isPlaying
    this.pendingCrossfadeFrom = undefined

    if (index === this.nextIndex && this.next) {
      this.current?.destroy()
      this.promoteNext()
    } else {
      this.current?.destroy()
      this.clearNext()
      this.setCurrent(this.createChannel(index))
    }

    this.display = this.current
    this.syncToChannel(this.current)
    this.currentIndex = index
    this.hasTriggeredFade = false
    if (this.isShuffled && this.playOrder.length === 0) {
      this.buildPlayOrder([index])
    }
    this.syncQueuePosition()
    this.prepareNext()
    this.onAdvance(this.currentIndex)
    if (shouldPlay) await this.resume()
  }

  async seek(time: number, index?: number) {
    if (
      index !== undefined &&
      index !== this.currentIndex &&
      index !== this.pendingCrossfadeFrom?.index
    ) {
      return
    }
    this.revertPendingCrossfade()
    if (index !== undefined && index !== this.currentIndex) return

    const channel = this.current
    if (!channel) return

    const { duration } = channel.audio
    const nextIndex = this.autoAdvanceIndex(this.currentIndex)
    // Seeking into the crossfade window would fade out mid-scrub, so move on.
    if (
      Number.isFinite(duration) &&
      duration > CROSSFADE_SECONDS &&
      time >= duration - CROSSFADE_SECONDS &&
      nextIndex !== undefined
    ) {
      if (nextIndex === this.currentIndex) this.restartInPlace(channel)
      else await this.skipToNext()
      return
    }

    channel.audio.currentTime = time
    channel.cutIn()
    this.hasTriggeredFade = false
    if (channel === this.display) this.patch({ currentTime: time })
  }

  setShuffle(enabled: boolean) {
    if (enabled === this.isShuffled) return
    this.isShuffled = enabled
    const shown = this.displayedIndex()
    if (enabled) {
      this.buildPlayOrder(
        this.currentIndex === shown ? [shown] : [shown, this.currentIndex]
      )
    }
    this.syncQueuePosition(shown)
    this.prepareNext()
  }

  private buildPlayOrder(pinned: number[]) {
    const rest = this.urls
      .map((_, index) => index)
      .filter((index) => !pinned.includes(index))
    this.playOrder = [...pinned, ...shuffle(rest)]
  }

  setRepeatMode(mode: RepeatMode) {
    if (mode === this.repeatMode) return
    this.repeatMode = mode
    this.prepareNext()
  }

  setVolume(volume: number) {
    this.volumeGain.gain.setTargetAtTime(
      Math.min(1, Math.max(0, volume)),
      this.context.currentTime,
      0.01
    )
  }

  destroy() {
    this.destroyActive()
    this.destroyFading()
    this.volumeGain.disconnect()
  }
}

export function createTimeout(ms: number, callback: () => void) {
  let id: ReturnType<typeof setTimeout> | undefined

  function stop() {
    clearTimeout(id)
    id = undefined
  }

  return {
    start() {
      stop()
      id = setTimeout(() => {
        id = undefined
        callback()
      }, ms)
    },
    stop,
    flush() {
      if (id === undefined) return
      stop()
      callback()
    },
  }
}

/**
 * Fires once after `delay`, then every `interval` until stopped. `stop()`
 * reports whether it fired, so a tap can be told apart from a hold.
 */
export function createHoldTimer(onFire: (repeat: boolean) => void) {
  let timeout: ReturnType<typeof setTimeout> | undefined
  let interval: ReturnType<typeof setInterval> | undefined
  let fired = false

  function stop() {
    clearTimeout(timeout)
    clearInterval(interval)
    timeout = undefined
    interval = undefined
    const didFire = fired
    fired = false
    return didFire
  }

  return {
    start(delay: number, repeatInterval?: number) {
      stop()
      timeout = setTimeout(() => {
        timeout = undefined
        fired = true
        onFire(false)
        if (fired && repeatInterval !== undefined) {
          interval = setInterval(() => onFire(true), repeatInterval)
        }
      }, delay)
    },
    stop,
  }
}

